import React, { useEffect, useState } from 'react'
import { Twitter, Facebook, Youtube, Instagram, Music2, MessageCircle } from 'lucide-react'
import { Ico } from './Icons.jsx'
import { useCMS } from './cmsContent.jsx'
import { useAppSettings } from '../../contexts/AppSettingsContext'
import { FOOTER_PAGES } from './footerPages.jsx'

const SOCIAL_ICONS = [
  { key: 'Twitter',   label: 'Twitter / X', Icon: Twitter },
  { key: 'Facebook',  label: 'Facebook',    Icon: Facebook },
  { key: 'Youtube',   label: 'YouTube',     Icon: Youtube },
  { key: 'Instagram', label: 'Instagram',   Icon: Instagram },
  { key: 'Tiktok',    label: 'TikTok',      Icon: Music2 },
  { key: 'Discord',   label: 'Discord',     Icon: MessageCircle },
]

export default function Footer() {
  const c = useCMS('footer')
  const settings = useAppSettings()
  const { logoUrl, appName } = settings
  // Link media sosial dari Vendor > Settings — sama seperti yang dipakai di
  // halaman login vendor, cuma tampilkan yang diisi & diaktifkan.
  const socialLinks = SOCIAL_ICONS
    .map(({ key, ...rest }) => ({
      ...rest,
      href: settings[`social${key}`],
      enabled: settings[`social${key}Enabled`],
    }))
    .filter((s) => s.href && s.enabled)
  const waHref = settings.supportWhatsapp ? `https://wa.me/${settings.supportWhatsapp}` : null
  const [modal, setModal] = useState(null)
  useEffect(() => {
    if (!modal) return
    const onKey = (e) => { if (e.key === 'Escape') setModal(null) }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [modal])

  // Tujuan tiap link footer ditentukan di kode (berdasarkan label) supaya
  // tidak ada tautan mati walau konten CMS lama masih menyimpan href "#".
  // Label tak dikenal tetap dipakai kalau href-nya valid; kalau tidak valid
  // (kosong/"#") atau menuju fitur yang tidak ada (Harga, Karier, Status
  // Sistem, Perubahan terbaru), link dibuang.
  const ROUTES = {
    'modul':             { href: '#modul' },
    'aplikasi warga':    { href: '#kelola' },
    'integrasi':         { modal: 'integrasi' },
    'faq':               { href: '#faq' },
    'hubungi kami':      waHref ? { href: waHref, external: true } : { href: '#cta' },
    'pusat bantuan':     { modal: 'pusat bantuan' },
    'panduan rt/rw':     { modal: 'panduan rt/rw' },
    'tentang':           { modal: 'tentang' },
    'mitra kelurahan':   { modal: 'mitra kelurahan' },
    'kebijakan privasi': { modal: 'kebijakan privasi' },
    'ketentuan layanan': { modal: 'ketentuan layanan' },
  }
  const REMOVED = ['harga', 'karier', 'status sistem', 'perubahan terbaru']
  const resolve = (l) => {
    const key = (l.label || '').trim().toLowerCase()
    if (REMOVED.includes(key)) return null
    if (ROUTES[key]) return { ...l, ...ROUTES[key] }
    const h = (l.href || '').trim()
    if (h && h !== '#') return l
    return null
  }
  const cols = (c.columns || [])
    .map((col) => ({ ...col, links: (col.links || []).map(resolve).filter(Boolean) }))
    .filter((col) => col.links.length > 0)
  const page = modal ? FOOTER_PAGES[modal] : null
  return (
    <footer>
      <div className="container">
        <div className="footer-top">
          <div className="footer-col">
            <a href="#" className="brand">
              {logoUrl ? (
                <img src={logoUrl} alt={appName} className="brand-mark-img" />
              ) : (
                <div className="brand-mark">R</div>
              )}
              <div className="brand-name">
                <span>{c.brand_name}</span>
                <small>{c.brand_subtitle}</small>
              </div>
            </a>
            <p className="footer-blurb">{c.blurb}</p>
            <div style={{display:'flex', gap:10}}>
              <a href="#" className="btn btn-ghost" style={{padding:'8px 14px', fontSize:13}}><Ico.Globe /> {c.lang_label}</a>
            </div>
            {socialLinks.length > 0 && (
              <div style={{display:'flex', gap:10, marginTop:16}}>
                {socialLinks.map(({ label, Icon, href }) => (
                  <a
                    key={label}
                    href={href}
                    target="_blank"
                    rel="noopener noreferrer"
                    title={label}
                    style={{
                      width:34, height:34, borderRadius:999, display:'flex',
                      alignItems:'center', justifyContent:'center',
                      border:'1px solid var(--line-2)', color:'var(--ink)',
                    }}
                  >
                    <Icon size={15} />
                  </a>
                ))}
              </div>
            )}
          </div>
          {cols.map((col, i) => (
            <div key={i} className="footer-col">
              <h5>{col.title}</h5>
              <ul>
                {(col.links || []).map((l, j) => (
                  <li key={j}>
                    {l.modal ? (
                      <a href="#" onClick={(e) => { e.preventDefault(); setModal(l.modal) }}>{l.label}</a>
                    ) : (
                      <a href={l.href} {...(l.external ? { target: '_blank', rel: 'noopener noreferrer' } : {})}>{l.label}</a>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        <div className="footer-bottom">
          <span>{c.copyright}</span>
          <span>{c.version_label}</span>
        </div>
      </div>
      {page && (
        <div className="info-overlay" onClick={() => setModal(null)} role="presentation">
          <div
            className="info-modal"
            role="dialog"
            aria-modal="true"
            aria-label={page.title}
            onClick={(e) => { e.stopPropagation(); if (e.target.closest('[data-close]')) setModal(null) }}
          >
            <button type="button" className="info-close" onClick={() => setModal(null)} aria-label="Tutup">×</button>
            <h3>{page.title}</h3>
            <div className="info-body">{page.render({ appName: appName || c.brand_name || 'Merata Digital', waHref })}</div>
          </div>
        </div>
      )}
    </footer>
  )
}
