import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import StatCard from '../components/StatCard';
import DonutChart from '../components/DonutChart';
import Pie3DChart from '../components/Pie3DChart';
import LineChart from '../components/LineChart';
import BarChart from '../components/BarChart';
import IplFinancialAnalyticsSection from '../components/dashboard/IplFinancialAnalyticsSection';
import BantuanSosialWidget from '../components/BantuanSosialWidget';
import StrataEkonomiSection from '../components/dashboard/StrataEkonomiSection';
import InformasiWargaSection from '../components/dashboard/InformasiWargaSection';
import { useAuth } from '../contexts/AuthContext';
import { useTenantProfile } from '../hooks/useTenantProfile';
import { exportElementToPdf, exportBantuanSosialPdf } from '../lib/exportSectionPdf';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Button } from '@/components/ui/button';
import { Users, Home, CheckCircle, AlertCircle, DollarSign, TrendingUp, Printer, Loader2 } from 'lucide-react';

const Dashboard = () => {
  const { token, user } = useAuth();
  const tenantProfile = useTenantProfile(token);
  const [loading, setLoading] = useState(true);
  const [dashboardData, setDashboardData] = useState(null);
  const [complianceData, setComplianceData] = useState(null);
  const [financeData, setFinanceData] = useState(null);
  const [iplTrendData, setIplTrendData] = useState(null);
  const [fundUsageData, setFundUsageData] = useState(null);
  const [delinquentList, setDelinquentList] = useState([]);
  const [delinquentPage, setDelinquentPage] = useState(1);
  const DELINQUENT_PER_PAGE = 10;
  const [bantuanStats, setBantuanStats] = useState(null);
  const [strataData, setStrataData] = useState(null);
  const [demografiData, setDemografiData] = useState(null);
  const [error, setError] = useState(null);
  const [selectedMonths, setSelectedMonths] = useState(6);
  const [saldoRW, setSaldoRW] = useState(null);  // null = belum load / tidak ada RW induk

  // Print PDF — Bantuan Sosial (dibangun native lewat autoTable) &
  // Statistik/Chart Warga (Strata Ekonomi + Demografi, capture canvas karena
  // isinya grafik donat/pie beneran).
  const strataDemografiRef = useRef(null);
  const [printingBantuan, setPrintingBantuan] = useState(false);
  const [printingStrata, setPrintingStrata] = useState(false);

  const wilayahLabel = tenantProfile?.label || '';

  const handlePrintBantuanSosial = async () => {
    if (!bantuanStats) return;
    setPrintingBantuan(true);
    try {
      await exportBantuanSosialPdf({
        stats: bantuanStats,
        title: 'Laporan Penerima Bantuan Sosial',
        subtitle: wilayahLabel,
        filename: `bantuan-sosial-${new Date().toISOString().slice(0, 10)}.pdf`,
      });
    } catch (err) {
      console.error('Gagal export PDF Bantuan Sosial:', err);
      alert('Gagal membuat PDF. Coba lagi.');
    } finally {
      setPrintingBantuan(false);
    }
  };

  const handlePrintStrataDemografi = async () => {
    if (!strataDemografiRef.current) return;
    setPrintingStrata(true);
    try {
      await exportElementToPdf(strataDemografiRef.current, {
        title: 'Laporan Statistik & Demografi Warga',
        subtitle: wilayahLabel,
        filename: `statistik-demografi-warga-${new Date().toISOString().slice(0, 10)}.pdf`,
        backgroundColor: '#ffffff',
      });
    } catch (err) {
      console.error('Gagal export PDF Statistik Demografi:', err);
      alert('Gagal membuat PDF. Coba lagi.');
    } finally {
      setPrintingStrata(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, [token, selectedMonths]);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const headers = token ? { Authorization: `Bearer ${token}` } : {};

      // Fetch KPI summary
      const summaryRes = await axios.get('/api/ipl/dashboard/summary', { headers });
      console.log('IPL Dashboard Summary:', summaryRes.data);
      setDashboardData(summaryRes.data);

      // Fetch compliance data
      const complianceRes = await axios.get('/api/ipl/dashboard/compliance', { headers });
      console.log('IPL Compliance Data:', complianceRes.data);
      setComplianceData(complianceRes.data);

      // Fetch delinquent warga list
      const delinquentRes = await axios.get('/api/ipl/dashboard/delinquent-warga', { headers });
      console.log('Delinquent Warga:', delinquentRes.data);
      setDelinquentList(delinquentRes.data || []);
      setDelinquentPage(1);

      // Fetch finance summary (pemasukan/pengeluaran)
      const financeRes = await axios.get(`/api/ipl/dashboard/finance-summary?months=${selectedMonths}`, { headers });
      console.log('Finance Summary:', financeRes.data);
      setFinanceData(financeRes.data);

      // Fetch IPL trend (tren iuran per bulan)
      const trendRes = await axios.get('/api/ipl/dashboard/ipl-trend', { headers });
      console.log('IPL Trend:', trendRes.data);
      setIplTrendData(trendRes.data);

      // Fetch fund usage (penggunaan dana per kategori)
      const fundRes = await axios.get('/api/ipl/dashboard/fund-usage', { headers });
      console.log('Fund Usage:', fundRes.data);
      setFundUsageData(fundRes.data);

      // Fetch bantuan sosial stats
      const bantuanRes = await axios.get('/api/ipl/dashboard/bantuan-stats', { headers });
      setBantuanStats(bantuanRes.data);

      // Fetch distribusi strata ekonomi (desil) — scoped ke tenant RT sendiri
      try {
        const strataRes = await axios.get('/api/warga/stats/strata-ekonomi', { headers });
        setStrataData(strataRes.data);
      } catch {
        setStrataData(null);
      }

      setError(null);

      // Fetch saldo RW induk (hanya untuk role admin/pengurus_rt, bukan warga)
      const isRTRole = user?.role === "admin" || user?.role === "pengurus_rt";
      if (isRTRole) {
        try {
          const saldoRwRes = await axios.get('/api/rw/finance/saldo-rw-for-rt', { headers });
          setSaldoRW(saldoRwRes.data);
        } catch {
          setSaldoRW(null); // RT tidak punya RW induk → sembunyikan widget
        }

        // Statistik demografi warga (Umur/Agama/Jenis Kelamin) — khusus dashboard RT, tidak untuk warga
        try {
          const demografiRes = await axios.get('/api/warga/stats/demografi', { headers });
          setDemografiData(demografiRes.data);
        } catch {
          setDemografiData(null);
        }
      }
    } catch (err) {
      console.error('Error fetching dashboard data:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value) => {
    return new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(value);
  };

  if (loading) {
    return (
      <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="text-center py-12">
          <p className="text-gray-600 dark:text-gray-400">Loading dashboard...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6 space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
        <div className="text-center py-12">
          <p className="text-red-600">Error: {error}</p>
        </div>
      </div>
    );
  }

  // Prepare compliance chart data
  const complianceChartData = complianceData ? [
    {
      label: complianceData.bayar.label,
      value: complianceData.bayar.count,
      percentage: complianceData.bayar.percentage,
      color: complianceData.bayar.color
    },
    {
      label: complianceData.belum.label,
      value: complianceData.belum.count,
      percentage: complianceData.belum.percentage,
      color: complianceData.belum.color
    }
  ] : [];

  const totalWarga = (dashboardData?.jumlah_warga_bayar || 0) + (dashboardData?.jumlah_warga_belum_bayar || 0);

  return (
    <div className="p-3 sm:p-6 space-y-4 sm:space-y-6 bg-[var(--rw-bg-page)] dark:bg-gray-900 min-h-full">
      {/* Breadcrumb */}
      <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
        <span>Dashboard</span>
        <span>/</span>
        <span className="text-gray-700 dark:text-gray-300 font-medium">Main</span>
      </div>

      

      {/* KPI Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-2 sm:gap-6">
        <StatCard
          title="Total Warga Aktif"
          value={dashboardData?.total_warga_aktif || 0}
          dropdown={false}
          icon={Users}
        />
        <StatCard
          title="Total Rumah"
          value={dashboardData?.total_rumah || 0}
          dropdown={false}
          icon={Home}
        />
        <StatCard
          title="Warga Sudah Bayar"
          value={dashboardData?.jumlah_warga_bayar || 0}
          dropdown={false}
          icon={CheckCircle}
        />
        <StatCard
          title="Warga Belum Bayar"
          value={dashboardData?.jumlah_warga_belum_bayar || 0}
          dropdown={false}
          icon={AlertCircle}
        />
      </div>

      {/* Financial Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-3 gap-2 sm:gap-6">
        <StatCard
          title="Total Terkumpul"
          value={formatCurrency(dashboardData?.total_terkumpul || 0)}
          dropdown={false}
          icon={TrendingUp}
        />
        <StatCard
          title="Total Tunggakan"
          value={formatCurrency(dashboardData?.total_tunggakan || 0)}
          dropdown={false}
          icon={AlertCircle}
        />
        <StatCard
          title="Saldo Kas IPL"
          value={formatCurrency(dashboardData?.saldo_kas_ipl || 0)}
          dropdown={false}
          icon={DollarSign}
        />
      
      </div>

      {/* RW Finance Summary — hanya untuk RT Admin */}
      {saldoRW !== null && (user?.role === "admin" || user?.role === "pengurus_rt") && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-1">
            Kas Keuangan {saldoRW.nama_rw || ''}
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 mb-4">Informasi keuangan dari RW induk (read-only)</p>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-green-50 dark:bg-green-900/20 rounded-lg p-4 border border-green-200 dark:border-green-800">
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Total Pemasukan</p>
              <p className="text-xl font-bold text-green-600">{formatCurrency(saldoRW.kas_masuk || 0)}</p>
            </div>
            <div className="bg-red-50 dark:bg-red-900/20 rounded-lg p-4 border border-red-200 dark:border-red-800">
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Total Pengeluaran</p>
              <p className="text-xl font-bold text-red-600">{formatCurrency(saldoRW.kas_keluar || 0)}</p>
            </div>
            <div className="bg-blue-50 dark:bg-blue-900/20 rounded-lg p-4 border border-blue-200 dark:border-blue-800">
              <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">Saldo Bersih</p>
              <p className="text-xl font-bold text-blue-600">{formatCurrency(saldoRW.saldo_rw || 0)}</p>
            </div>
          </div>
        </div>
      )}

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Compliance Chart */}
        {complianceChartData.length > 0 && (
          <div className="w-full">
            <DonutChart
              title="Status Kepatuhan Pembayaran"
              data={complianceChartData}
              totalLabel={`(${totalWarga} total)`}
            />
          </div>
        )}
      {/* Second Row: IPL Trend & Fund Usage */}
      
        

        {/* Fund Usage Chart */}
        {fundUsageData && fundUsageData.data.length > 0 && (
          <div className="w-full">
            <DonutChart
              title="Penggunaan Dana IPL per Kategori"
              data={fundUsageData.data.map(item => ({
                label: item.label,
                value: item.value,
                percentage: item.percentage,
                color: item.color
              }))}
              totalLabel={`(${fundUsageData.total_spent.toLocaleString('id-ID')})`}
            />
          </div>
        )}

        {/* Summary Stats Box */}
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-4">
            Ringkasan Keuangan
          </h3>
          <div className="space-y-4">
            <div className="flex justify-between items-center pb-4 border-b border-[var(--rw-border)] dark:border-gray-700">
              <span className="text-gray-600 dark:text-gray-400">Total Iuran Bulanan</span>
              <span className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(dashboardData?.total_terkumpul || 0)}
              </span>
            </div>
            <div className="flex justify-between items-center pb-4 border-b border-[var(--rw-border)] dark:border-gray-700">
              <span className="text-gray-600 dark:text-gray-400">Tunggakan</span>
              <span className="text-lg font-semibold text-red-600">
                {formatCurrency(dashboardData?.total_tunggakan || 0)}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-600 dark:text-gray-400">Saldo Kas Tersedia</span>
              <span className="text-lg font-semibold text-green-600">
                {formatCurrency(dashboardData?.saldo_kas_ipl || 0)}
              </span>
            </div>
          </div>
        </div>
      
        
      </div>

     
      <IplFinancialAnalyticsSection />

      {/* Informasi RT — Pin Informasi + list per kategori, khusus dashboard warga */}
      {user?.role === "warga" && <InformasiWargaSection />}

      {/* Bantuan Sosial Widget */}
      {bantuanStats && (
        <div>
          {user?.role !== "warga" && (
            <div className="flex justify-end mb-2">
              <Button
                variant="outline"
                size="sm"
                onClick={handlePrintBantuanSosial}
                disabled={printingBantuan}
                className="border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400"
              >
                {printingBantuan ? (
                  <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" />Membuat PDF...</>
                ) : (
                  <><Printer className="h-4 w-4 mr-1.5" />Print PDF</>
                )}
              </Button>
            </div>
          )}
          <BantuanSosialWidget stats={bantuanStats} />
        </div>
      )}

      {/* Distribusi Strata Ekonomi + Statistik Demografi Warga — dibungkus supaya bisa di-Print PDF sekaligus (disembunyikan untuk role warga) */}
      {user?.role !== "warga" && (
        <div>
          <div className="flex justify-end mb-2">
            <Button
              variant="outline"
              size="sm"
              onClick={handlePrintStrataDemografi}
              disabled={printingStrata}
              className="border-orange-600 text-orange-700 hover:bg-orange-50 dark:border-orange-500 dark:text-orange-400"
            >
              {printingStrata ? (
                <><Loader2 className="h-4 w-4 mr-1.5 animate-spin" />Membuat PDF...</>
              ) : (
                <><Printer className="h-4 w-4 mr-1.5" />Print PDF</>
              )}
            </Button>
          </div>
          <div ref={strataDemografiRef} className="space-y-6">
            <StrataEkonomiSection strataData={strataData} mode="rt" title="Distribusi Strata Ekonomi Warga (RT Ini)" />

            {/* Statistik Demografi Warga (Umur/Agama/Jenis Kelamin) — khusus dashboard RT, TIDAK muncul untuk warga */}
            {(user?.role === "admin" || user?.role === "pengurus_rt") && demografiData && demografiData.total > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                <DonutChart
                  title="Jumlah Warga Berdasarkan Umur"
                  data={demografiData.by_umur}
                  totalLabel={`(${demografiData.total} total)`}
                />
                <DonutChart
                  title="Jumlah Warga Berdasarkan Agama"
                  data={demografiData.by_agama}
                  totalLabel={`(${demografiData.total} total)`}
                />
                <DonutChart
                  title="Jumlah Warga Berdasarkan Jenis Kelamin"
                  data={demografiData.by_gender}
                  totalLabel={`(${demografiData.total} total)`}
                />
              </div>
            )}

            {/* Statistik tambahan: Status Warga / Kewarganegaraan (WNI-WNA) / Pekerjaan — khusus dashboard RT */}
            {(user?.role === "admin" || user?.role === "pengurus_rt") && demografiData && demografiData.total > 0 && (
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                <Pie3DChart
                  title="Jumlah Warga Berdasarkan Status"
                  data={demografiData.by_status}
                  totalLabel={`(${demografiData.total} total)`}
                />
                <Pie3DChart
                  title="Jumlah Warga Berdasarkan Kewarganegaraan"
                  data={demografiData.by_kewarganegaraan}
                  totalLabel={`(${demografiData.total} total)`}
                />
                <Pie3DChart
                  title="Jumlah Warga Berdasarkan Pekerjaan"
                  data={demografiData.by_pekerjaan}
                  totalLabel={`(${demografiData.total} total)`}
                />
              </div>
            )}
          </div>
        </div>
      )}

       {/* Delinquent List Table */}
      {delinquentList.length > 0 && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow">
          <div className="p-6 border-b border-[var(--rw-border)] dark:border-gray-700">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
              Warga Belum Membayar IPL
            </h3>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Total {delinquentList.length} warga dengan tagihan belum lunas
            </p>
          </div>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Blok Rumah</TableHead>
                <TableHead>Pemilik Rumah</TableHead>
                <TableHead className="text-right">Total Tagihan</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {delinquentList
                .slice((delinquentPage - 1) * DELINQUENT_PER_PAGE, delinquentPage * DELINQUENT_PER_PAGE)
                .map((item) => (
                <TableRow key={item.rumah_id}>
                  <TableCell className="font-medium">{item.blok_no}</TableCell>
                  <TableCell>{item.pemilik_sah}</TableCell>
                  <TableCell className="text-right text-red-600 font-semibold">
                    {formatCurrency(item.total_tagihan_belum)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {delinquentList.length > DELINQUENT_PER_PAGE && (
            <div className="flex justify-between items-center text-sm text-gray-600 dark:text-gray-400 px-6 py-4 border-t border-[var(--rw-border)] dark:border-gray-700">
              <span>
                {(delinquentPage - 1) * DELINQUENT_PER_PAGE + 1}-
                {Math.min(delinquentPage * DELINQUENT_PER_PAGE, delinquentList.length)} dari {delinquentList.length}
              </span>
              <div className="flex gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setDelinquentPage((p) => Math.max(1, p - 1))}
                  disabled={delinquentPage === 1}
                  className="dark:border-gray-700 dark:text-gray-200"
                >
                  Sebelumnya
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() =>
                    setDelinquentPage((p) =>
                      Math.min(Math.ceil(delinquentList.length / DELINQUENT_PER_PAGE), p + 1)
                    )
                  }
                  disabled={delinquentPage === Math.ceil(delinquentList.length / DELINQUENT_PER_PAGE)}
                  className="dark:border-gray-700 dark:text-gray-200"
                >
                  Selanjutnya
                </Button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Empty State */}
      {delinquentList.length === 0 && (
        <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg shadow p-12 text-center">
          <p className="text-gray-900 dark:text-white font-bold text-lg">
            Semua warga sudah melunasi pembayaran IPL <span className="text-green-500">✓</span>
          </p>
        </div>
      )}
    </div>
  );
};

export default Dashboard;