import React from 'react';
import { Button } from '../../components/ui/button';
import { Input } from '../../components/ui/input';
import { Label } from '../../components/ui/label';
import { Smartphone, Lock, AlertCircle, Headset, ArrowRight } from 'lucide-react';
import { API_BASE_URL } from '../../config/api';

// Tema login "Split Tengah" — pembagian lurus 50/50, tanpa lengkungan,
// konten di kedua sisi rata tengah, dipisahkan garis tegas di tengah layar.
export default function LoginLayoutSplitCenter({
  branding, logo, appTitle, appDescription, vendorAppName, primaryColorStyle,
  phone, setPhone, password, setPassword, error, isLoading, handleSubmit, navigate,
  SOCIAL_ICONS,
}) {
  return (
    <div
      className="min-h-screen flex flex-col lg:flex-row bg-[var(--rw-bg-page)] dark:bg-gray-950"
      style={primaryColorStyle}
    >
      {/* Left Panel - solid, rata tengah, garis pembatas tegas di kanan */}
      <div className="relative lg:w-1/2 min-h-[35vh] lg:min-h-screen flex items-center justify-center border-b lg:border-b-0 lg:border-r border-[color-mix(in_srgb,var(--rw-primary)_40%,black)]">
        {branding?.login_bg_url && (
          <div
            className="absolute inset-0 bg-cover bg-center"
            style={{ backgroundImage: `url(${API_BASE_URL}${branding.login_bg_url})` }}
          />
        )}
        <div
          className={`absolute inset-0 bg-[var(--rw-primary)] ${branding?.login_bg_url ? 'opacity-75' : ''}`}
        />

        {vendorAppName && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 lg:left-8 lg:translate-x-0 z-10 text-[10px] lg:text-xs font-medium tracking-wide uppercase text-white/50">
            {vendorAppName}
          </div>
        )}

        <div className="relative z-10 flex flex-col items-center text-center text-white px-8 py-10 lg:py-0">
          <img src={logo} alt={appTitle} className="w-32 lg:w-48 mb-6" />
          <h1 className="text-2xl lg:text-3xl font-bold">{appTitle}</h1>
          <h2 className="text-lg lg:text-xl font-semibold text-white/80 mt-1">Manajemen Pengurus</h2>
          {branding?.login_caption && (
            <p className="mt-1 text-sm text-white/60 max-w-xs">{branding.login_caption}</p>
          )}
          <p className="mt-4 text-sm text-white/70 max-w-xs">{appDescription}</p>
        </div>
      </div>

      {/* Right Panel - form, rata tengah penuh */}
      <div className="flex-1 lg:w-1/2 flex items-center justify-center p-6 sm:p-8 lg:p-12">
        <div className="w-full max-w-sm space-y-8">
          <div className="text-center">
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white">Masuk Akun</h2>
            <p className="mt-2 text-gray-500 dark:text-gray-400">Masuk dengan No WhatsApp terdaftar</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-2">
              <Label htmlFor="phone" className="text-gray-700 dark:text-gray-300">No WhatsApp</Label>
              <div className="relative">
                <Smartphone className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                <Input
                  id="phone" type="tel" placeholder="08xxxxxxxxxx"
                  value={phone} onChange={(e) => setPhone(e.target.value)}
                  className="pl-12 h-12 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 border-[var(--rw-border)] dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-[var(--rw-primary)] focus:border-transparent"
                  disabled={isLoading} autoComplete="tel"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="password" className="text-gray-700 dark:text-gray-300">Password</Label>
              <div className="relative">
                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                <Input
                  id="password" type="password" placeholder="Masukkan password"
                  value={password} onChange={(e) => setPassword(e.target.value)}
                  className="pl-12 h-12 bg-[var(--rw-bg-card-alt)] dark:bg-gray-800 border-[var(--rw-border)] dark:border-gray-700 rounded-xl focus:ring-2 focus:ring-[var(--rw-primary)] focus:border-transparent"
                  disabled={isLoading} autoComplete="current-password"
                />
              </div>
            </div>

            {error && (
              <div className="flex items-center gap-2 p-3 bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-xl text-red-600 dark:text-red-400">
                <AlertCircle className="h-4 w-4 flex-shrink-0" />
                <p className="text-sm">{error}</p>
              </div>
            )}

            <Button
              type="submit"
              className="w-full h-12 bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white font-semibold rounded-xl shadow-lg shadow-[color-mix(in_srgb,var(--rw-primary)_20%,transparent)] transition-all hover:shadow-[color-mix(in_srgb,var(--rw-primary)_40%,transparent)] hover:scale-[1.02]"
              disabled={isLoading}
            >
              {isLoading ? 'Memproses...' : 'Login'}
            </Button>

            <div className="flex items-center justify-center gap-4 pt-2">
              <span className="text-sm text-gray-500 dark:text-gray-400">Belum punya akun?</span>
              <Button
                type="button" variant="ghost"
                className="text-[var(--rw-primary)] font-semibold hover:text-[color-mix(in_srgb,var(--rw-primary)_70%,black)] hover:bg-[color-mix(in_srgb,var(--rw-primary)_15%,white)] dark:hover:bg-[color-mix(in_srgb,var(--rw-primary)_20%,transparent)] px-4"
                onClick={() => navigate('/register')} disabled={isLoading}
              >
                Daftar Warga
              </Button>
            </div>

            {branding?.support_whatsapp && (
              <div className="flex justify-center pt-2">
                <a
                  href={`https://wa.me/${branding.support_whatsapp}`} target="_blank" rel="noopener noreferrer"
                  className="flex items-center gap-3 bg-white dark:bg-gray-900 border border-[var(--rw-border)] dark:border-gray-700 rounded-2xl shadow-md px-4 py-3 hover:shadow-lg transition-shadow max-w-full"
                >
                  <div className="w-9 h-9 rounded-full bg-[color-mix(in_srgb,var(--rw-primary)_15%,white)] dark:bg-[color-mix(in_srgb,var(--rw-primary)_25%,black)] flex items-center justify-center flex-shrink-0">
                    <Headset size={16} className="text-[var(--rw-primary)]" />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-gray-500 dark:text-gray-400">Butuh bantuan?</p>
                    <p className="text-sm font-semibold text-gray-800 dark:text-white truncate">Hubungi Pengurus {appTitle}</p>
                  </div>
                  <ArrowRight size={16} className="text-gray-400 flex-shrink-0" />
                </a>
              </div>
            )}

            {branding?.social && Object.values(branding.social).some(Boolean) && (
              <div className="flex items-center justify-center gap-3 pt-8">
                {SOCIAL_ICONS.filter(({ key }) => branding.social[key]).map(({ key, label, Icon }) => (
                  <a
                    key={key} href={branding.social[key]} target="_blank" rel="noopener noreferrer" title={label}
                    className="w-9 h-9 rounded-full flex items-center justify-center border border-[var(--rw-border)] dark:border-gray-700 text-gray-500 dark:text-gray-400 hover:text-[var(--rw-primary)] hover:border-[var(--rw-primary)] transition-colors"
                  >
                    <Icon size={16} />
                  </a>
                ))}
              </div>
            )}
          </form>
        </div>
      </div>
    </div>
  );
}
