import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useAuth } from './AuthContext';
import { API_BASE_URL } from '../config/api';

const RWFilterContext = createContext(null);

const RW_ROLES = ['rw', 'pengurus_rw', 'admin'];

export const RWFilterProvider = ({ children }) => {
  const { user, token } = useAuth();
  const [rtList, setRtList] = useState([]);
  const [selectedRT, setSelectedRT] = useState(null);

  const isRWUser = user?.role && RW_ROLES.includes(user.role);

  const fetchRTList = useCallback(async () => {
    if (!token || !isRWUser) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/rw/rt-list`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setRtList(data?.rt_list || []);
      }
    } catch (_) {}
  }, [token, isRWUser]);

  useEffect(() => { fetchRTList(); }, [fetchRTList]);

  // Reset selection when user logs out or changes
  useEffect(() => {
    if (!isRWUser) {
      setSelectedRT(null);
      setRtList([]);
    }
  }, [isRWUser]);

  return (
    <RWFilterContext.Provider value={{
      rtList,
      selectedRT,
      setSelectedRT,
      rtId: selectedRT?.id || null,
    }}>
      {children}
    </RWFilterContext.Provider>
  );
};

export const useRWFilter = () => {
  const ctx = useContext(RWFilterContext);
  if (!ctx) throw new Error('useRWFilter must be used within RWFilterProvider');
  return ctx;
};
