import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useAuth } from '@/contexts/AuthContext';
import { useTenantProfile } from '@/hooks/useTenantProfile';
import { API_BASE_URL } from '@/config/api';
import { useAppSettings } from '@/contexts/AppSettingsContext';
import {
  MessageCircle, MessageSquare, HelpCircle, Headset,
  X, Send, Paperclip, ChevronLeft, Loader2,
} from 'lucide-react';

const ALLOWED_ROLES = ['admin', 'pengurus_rw', 'pengurus_kelurahan'];
const AGENT_POLL_MS = 60_000;   // daftar agent jarang berubah
const CHAT_POLL_MS  = 4_000;    // polling balasan agent saat chat dibuka
const UNREAD_POLL_MS = 15_000;  // badge balasan belum dibaca
const MAX_FILE_BYTES = 8 * 1024 * 1024;

// Harus sinkron dengan SUPPORT_THEMES/SUPPORT_ICONS di VendorSettings.jsx
// dan daftar nilai yang divalidasi backend (app_settings.py).
const THEME_COLORS = { green: '#16a34a', blue: '#2563eb', dark: '#1f2937' };
const ICONS = {
  'message-circle': MessageCircle,
  'headset': Headset,
  'help-circle': HelpCircle,
  'message-square': MessageSquare,
};

function initials(name) {
  return (name || '?').trim().charAt(0).toUpperCase();
}

// Avatar agent: pakai foto kalau vendor sudah mengunggahnya, kalau tidak
// jatuh ke inisial nama seperti sebelumnya.
function AgentAvatar({ agent, size = 40, color }) {
  const url = agent?.avatar_url ? `${API_BASE_URL}${agent.avatar_url}` : null;
  if (url) {
    return (
      <img src={url} alt={agent.name}
        className="rounded-full object-cover flex-shrink-0"
        style={{ width: size, height: size }} />
    );
  }
  return (
    <div className="rounded-full flex items-center justify-center font-bold flex-shrink-0 text-white"
      style={{ width: size, height: size, background: color, fontSize: size * 0.4 }}>
      {initials(agent?.name)}
    </div>
  );
}

function jam(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
  } catch { return ''; }
}

export default function SupportChatButton() {
  const { token, user } = useAuth();
  const tenantProfile = useTenantProfile(token);
  const wilayahLabel = tenantProfile?.label || null;
  const { supportWidget } = useAppSettings();

  const cfg = supportWidget || {};
  const brand = cfg.color || THEME_COLORS[cfg.theme] || THEME_COLORS.green;
  const BrandIcon = ICONS[cfg.icon] || MessageCircle;
  const onRight = cfg.position === 'right';

  const [unread, setUnread] = useState({ total: 0, per_agent: {} });

  const [agents, setAgents] = useState([]);
  const [loadingAgents, setLoadingAgents] = useState(true);
  const [open, setOpen] = useState(false);
  const [activeAgent, setActiveAgent] = useState(null);   // null = tampilkan daftar agent

  const [messages, setMessages] = useState([]);
  const [loadingChat, setLoadingChat] = useState(false);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [attachment, setAttachment] = useState(null);     // { data, mimetype, filename, previewName }
  const [errorMsg, setErrorMsg] = useState('');

  const listEndRef = useRef(null);
  const fileRef = useRef(null);

  const allowed = !!token && !!user && ALLOWED_ROLES.includes(user.role);
  const authHeader = useCallback(() => ({ Authorization: `Bearer ${token}` }), [token]);

  // ── Daftar support agent ────────────────────────────────────────────────
  const fetchAgents = useCallback(async () => {
    if (!token || !allowed) { setAgents([]); setLoadingAgents(false); return; }
    try {
      const res = await fetch(`${API_BASE_URL}/api/support-agents/mine`, { headers: authHeader() });
      const data = res.ok ? await res.json() : [];
      setAgents(Array.isArray(data) ? data : []);
    } catch {
      setAgents([]);
    } finally {
      setLoadingAgents(false);
    }
  }, [token, allowed, authHeader]);

  useEffect(() => {
    fetchAgents();
    const id = setInterval(fetchAgents, AGENT_POLL_MS);
    return () => clearInterval(id);
  }, [fetchAgents]);

  // ── Badge balasan agent yang belum dibaca ───────────────────────────────
  const fetchUnread = useCallback(async () => {
    if (!token || !allowed) return;
    try {
      const res = await fetch(`${API_BASE_URL}/api/support-chat/unread`, { headers: authHeader() });
      if (res.ok) {
        const d = await res.json();
        setUnread({ total: d.total || 0, per_agent: d.per_agent || {} });
      }
    } catch { /* diamkan */ }
  }, [token, allowed, authHeader]);

  useEffect(() => {
    fetchUnread();
    const id = setInterval(fetchUnread, UNREAD_POLL_MS);
    return () => clearInterval(id);
  }, [fetchUnread]);

  // ── Riwayat chat + polling balasan agent ────────────────────────────────
  const fetchHistory = useCallback(async (agentId, showSpinner = false) => {
    if (!agentId) return;
    if (showSpinner) setLoadingChat(true);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/support-chat/history?agent_id=${encodeURIComponent(agentId)}`,
        { headers: authHeader() },
      );
      if (res.ok) {
        const data = await res.json();
        setMessages(Array.isArray(data.messages) ? data.messages : []);
      }
    } catch { /* diamkan — polling berikutnya coba lagi */ }
    finally { if (showSpinner) setLoadingChat(false); }
  }, [authHeader]);

  useEffect(() => {
    if (!open || !activeAgent) return;
    // Membuka chat menandai balasan terbaca di backend — segarkan badge.
    fetchHistory(activeAgent.id, true).then(fetchUnread);
    const id = setInterval(() => fetchHistory(activeAgent.id), CHAT_POLL_MS);
    return () => clearInterval(id);
  }, [open, activeAgent, fetchHistory, fetchUnread]);

  useEffect(() => {
    listEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages, loadingChat]);

  // ── Lampiran ────────────────────────────────────────────────────────────
  const handleFile = (file) => {
    if (!file) return;
    if (file.size > MAX_FILE_BYTES) {
      setErrorMsg('Ukuran file maksimal 8 MB');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || '');
      const base64 = result.includes(',') ? result.split(',')[1] : result;
      setAttachment({
        data: base64,
        mimetype: file.type || 'application/octet-stream',
        filename: file.name,
      });
      setErrorMsg('');
    };
    reader.readAsDataURL(file);
  };

  // ── Kirim pesan ─────────────────────────────────────────────────────────
  const handleSend = async () => {
    const text = input.trim();
    if ((!text && !attachment) || sending || !activeAgent) return;
    setSending(true);
    setErrorMsg('');
    try {
      const res = await fetch(`${API_BASE_URL}/api/support-chat/send`, {
        method: 'POST',
        headers: { ...authHeader(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ agent_id: activeAgent.id, text, media: attachment || null }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal mengirim pesan');
      setMessages(m => [...m, data]);
      setInput('');
      setAttachment(null);
      if (fileRef.current) fileRef.current.value = '';
    } catch (e) {
      setErrorMsg(e.message);
    } finally {
      setSending(false);
    }
  };

  const openAgent = (agent) => {
    setActiveAgent(agent);
    setMessages([]);
    setErrorMsg('');
    setInput('');
    setAttachment(null);
  };

  if (!allowed || loadingAgents || agents.length === 0) return null;

  return (
    <>
      {/* ── FLOATING BUTTON — sisi & tampilan mengikuti setting vendor ── */}
      <button
        onClick={() => setOpen(o => !o)}
        className="fixed bottom-5 z-[9000] flex items-center gap-2 h-12 px-4 rounded-full text-white shadow-2xl transition-all hover:brightness-110"
        style={{
          [onRight ? 'right' : 'left']: 16,
          background: brand,
          boxShadow: '0 4px 20px rgba(0,0,0,0.28)',
        }}
        title="Hubungi Support"
      >
        {open ? <X size={20} /> : <BrandIcon size={20} />}
        {!open && <span className="text-sm font-semibold hidden sm:inline">Butuh bantuan?</span>}
        {!open && unread.total > 0 && (
          <span className="absolute -top-1 -right-1 min-w-[20px] h-5 px-1 rounded-full bg-red-500 text-white text-[11px] font-bold flex items-center justify-center ring-2 ring-white">
            {unread.total > 99 ? '99+' : unread.total}
          </span>
        )}
      </button>

      {/* ── PANEL CHAT (menempel di atas tombol, bukan modal tengah) ── */}
      {open && (
        <div
          // z-index di atas tombol SOS (9000): saat panel dibuka, panel
          // menutupinya rapi alih-alih tombol menembus di atas panel.
          className="fixed z-[9050] w-[92vw] max-w-sm rounded-2xl shadow-2xl overflow-hidden flex flex-col bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700"
          style={{ bottom: 76, [onRight ? 'right' : 'left']: 16, maxHeight: 'min(70vh, 560px)' }}
        >
          {/* Header */}
          <div className="px-4 py-3 flex items-center gap-2 flex-shrink-0" style={{ background: brand }}>
            {activeAgent && (
              <button onClick={() => setActiveAgent(null)} className="text-white/90 hover:text-white -ml-1">
                <ChevronLeft size={20} />
              </button>
            )}
            <div className="flex-1 min-w-0">
              <p className="text-white font-bold text-sm leading-tight truncate">
                {activeAgent ? activeAgent.name : 'Support Ruang Warga'}
              </p>
              <p className="text-white/75 text-xs truncate">
                {activeAgent
                  ? (activeAgent.role_label || 'Tim Support')
                  : 'Pilih kontak untuk mulai chat'}
              </p>
            </div>
            <button onClick={() => setOpen(false)} className="text-white/80 hover:text-white">
              <X size={18} />
            </button>
          </div>

          {/* ── Daftar agent ── */}
          {!activeAgent && (
            <div className="overflow-y-auto divide-y divide-gray-100 dark:divide-gray-700">
              {wilayahLabel && (
                <div className="px-4 py-2.5 text-[11px] text-gray-600 dark:text-gray-300"
                  style={{ background: `${brand}14` }}>
                  Anda terhubung sebagai <strong>{user?.fullname}</strong> — {wilayahLabel}
                </div>
              )}
              {agents.map(agent => {
                const n = unread.per_agent?.[agent.id] || 0;
                return (
                  <button
                    key={agent.id}
                    onClick={() => openAgent(agent)}
                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-gray-50 dark:hover:bg-gray-800 text-left transition-colors"
                  >
                    <AgentAvatar agent={agent} size={40} color={brand} />
                    <div className="flex-1 min-w-0">
                      <p className="text-xs text-gray-400">{agent.role_label || 'Support'}</p>
                      <p className="text-sm font-semibold text-gray-800 dark:text-gray-100 truncate">{agent.name}</p>
                    </div>
                    {n > 0 ? (
                      <span className="flex-shrink-0 min-w-[20px] h-5 px-1 rounded-full bg-red-500 text-white text-[11px] font-bold flex items-center justify-center">
                        {n > 99 ? '99+' : n}
                      </span>
                    ) : (
                      <BrandIcon size={16} className="flex-shrink-0" style={{ color: brand }} />
                    )}
                  </button>
                );
              })}
              <div className="px-4 py-2.5 text-[11px] text-gray-400 text-center">
                Pesan diteruskan ke WhatsApp tim support
              </div>
            </div>
          )}

          {/* ── Ruang chat ── */}
          {activeAgent && (
            <>
              <div className="flex-1 overflow-y-auto p-3 space-y-2 bg-gray-50 dark:bg-gray-800/50 min-h-[220px]">
                {loadingChat && messages.length === 0 && (
                  <div className="flex justify-center py-6">
                    <Loader2 size={20} className="animate-spin" style={{ color: brand }} />
                  </div>
                )}

                {!loadingChat && messages.length === 0 && (
                  <div className="text-center py-6 px-4">
                    <div className="flex justify-center mb-2">
                      <AgentAvatar agent={activeAgent} size={48} color={brand} />
                    </div>
                    <p className="text-sm font-semibold text-gray-700 dark:text-gray-200">{activeAgent.name}</p>
                    <p className="text-xs text-gray-400 mt-1">
                      Kirim pesan pertama Anda. Identitas &amp; wilayah Anda otomatis disertakan.
                    </p>
                  </div>
                )}

                {messages.map(m => (
                  <div key={m.id} className={`flex ${m.direction === 'out' ? 'justify-end' : 'justify-start'}`}>
                    <div className={`max-w-[80%] rounded-2xl px-3 py-2 text-sm ${
                      m.direction === 'out'
                        ? 'text-white rounded-br-sm'
                        : 'bg-white dark:bg-gray-700 text-gray-800 dark:text-gray-100 border border-gray-200 dark:border-gray-600 rounded-bl-sm'
                    }`}
                      style={m.direction === 'out' ? { background: brand } : undefined}>
                      {m.media_url && (
                        (m.media_mimetype || '').startsWith('image/') ? (
                          <a href={`${API_BASE_URL}${m.media_url}`} target="_blank" rel="noopener noreferrer">
                            <img src={`${API_BASE_URL}${m.media_url}`} alt={m.media_filename || 'lampiran'}
                              className="rounded-lg mb-1 max-h-40 object-cover" />
                          </a>
                        ) : (
                          <a href={`${API_BASE_URL}${m.media_url}`} target="_blank" rel="noopener noreferrer"
                            className="flex items-center gap-1.5 underline mb-1 text-xs">
                            <Paperclip size={12} /> {m.media_filename || 'Lampiran'}
                          </a>
                        )
                      )}
                      {m.body && <p className="whitespace-pre-wrap break-words">{m.body}</p>}
                      <p className={`text-[10px] mt-0.5 text-right ${m.direction === 'out' ? 'text-white/70' : 'text-gray-400'}`}>
                        {jam(m.created_at)}
                      </p>
                    </div>
                  </div>
                ))}
                <div ref={listEndRef} />
              </div>

              {/* Error */}
              {errorMsg && (
                <div className="px-3 py-2 bg-red-50 border-t border-red-200 text-xs text-red-600 flex-shrink-0">
                  {errorMsg}
                </div>
              )}

              {/* Lampiran terpilih */}
              {attachment && (
                <div className="px-3 py-2 bg-gray-50 dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700 flex items-center gap-2 text-xs flex-shrink-0">
                  <Paperclip size={13} className="text-gray-400 flex-shrink-0" />
                  <span className="flex-1 truncate text-gray-600 dark:text-gray-300">{attachment.filename}</span>
                  <button onClick={() => { setAttachment(null); if (fileRef.current) fileRef.current.value = ''; }}
                    className="text-gray-400 hover:text-red-500">
                    <X size={14} />
                  </button>
                </div>
              )}

              {/* Input */}
              <div className="flex-shrink-0 p-2.5 border-t border-gray-200 dark:border-gray-700 flex items-end gap-1.5">
                <input ref={fileRef} type="file" className="hidden"
                  accept="image/*,application/pdf"
                  onChange={e => handleFile(e.target.files?.[0])} />
                <button onClick={() => fileRef.current?.click()}
                  className="flex-shrink-0 w-9 h-9 rounded-full text-gray-400 hover:text-green-600 hover:bg-gray-100 dark:hover:bg-gray-800 flex items-center justify-center transition-colors"
                  title="Lampirkan gambar / PDF">
                  <Paperclip size={17} />
                </button>
                <textarea
                  rows={1}
                  value={input}
                  onChange={e => setInput(e.target.value)}
                  onKeyDown={e => {
                    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
                  }}
                  placeholder="Ketik pesan..."
                  className="flex-1 resize-none max-h-24 text-sm border border-gray-200 dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100 rounded-2xl px-3 py-2 focus:outline-none focus:ring-2 focus:ring-green-500"
                />
                <button
                  onClick={handleSend}
                  disabled={sending || (!input.trim() && !attachment)}
                  className="flex-shrink-0 w-9 h-9 rounded-full disabled:opacity-40 text-white flex items-center justify-center transition-all hover:brightness-110"
                  style={{ background: brand }}
                >
                  {sending ? <Loader2 size={15} className="animate-spin" /> : <Send size={15} />}
                </button>
              </div>
            </>
          )}
        </div>
      )}
    </>
  );
}
