/**
 * Konversi kode negara ISO 3166-1 alpha-2 (mis. 'ID', 'MY') menjadi emoji bendera.
 * Trik: emoji bendera Unicode dibentuk dari 2 "Regional Indicator Symbol" yang
 * masing-masing adalah huruf A-Z + offset 0x1F1E6, jadi tidak perlu gambar/API eksternal.
 */
export function countryCodeToFlag(code) {
  if (!code || code.length !== 2) return '🏳️';
  const upper = code.toUpperCase();
  const codePoints = [...upper].map(c => 0x1f1e6 + (c.charCodeAt(0) - 65));
  if (codePoints.some(cp => cp < 0x1f1e6 || cp > 0x1f1ff)) return '🏳️';
  return String.fromCodePoint(...codePoints);
}
