const uid = () => Math.random().toString(36).slice(2, 10);

// Format nilai isian sesuai tipe field — dipakai di PDF export & tampilan detail,
// supaya checkbox tampil "Ya/Tidak" bukan true/false mentah.
const formatFieldValue = (fieldOrCol, value) => {
  if (fieldOrCol.type === 'checkbox') return value ? 'Ya' : 'Tidak';
  if (value === undefined || value === null || value === '') return '-';
  return String(value);
};

// ─────────────────────────────────────────────────────────────────────────
// EXPORT PDF — kop surat mengikuti konvensi surat resmi Kelurahan (logo
// Garuda + nama Kelurahan/Kabupaten dari Profil Kelurahan), bukan brand tetap.
// ─────────────────────────────────────────────────────────────────────────
function createLetterheadPdf(profil, kopLogoUrl) {
  const pdf = new jsPDF('p', 'mm', 'a4');
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const margin = 20;

  const namaKelurahan = (profil?.nama_kelurahan || '').toUpperCase();
  const kabupaten = profil?.kabupaten || '';
  const alamatBawah = [profil?.kecamatan, profil?.kabupaten, profil?.provinsi].filter(Boolean).join(', ');

  const drawHeader = async () => {
    if (kopLogoUrl) {
      try {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.src = kopLogoUrl;
        await new Promise((resolve, reject) => {
          img.onload = resolve;
          img.onerror = reject;
        });
        pdf.addImage(img, 'PNG', margin, 8, 22, 22);
      } catch { /* logo tidak ditemukan, lanjut tanpa logo */ }
    }

    pdf.setTextColor(0, 0, 0);
    pdf.setFontSize(14);
    pdf.setFont('helvetica', 'bold');
    pdf.text(`PEMERINTAH ${kabupaten.toUpperCase()}`, pageWidth / 2, 15, { align: 'center' });

    pdf.setFontSize(13);
    pdf.text(`KELURAHAN / DESA ${namaKelurahan}`, pageWidth / 2, 22, { align: 'center' });

    pdf.setFontSize(9);
    pdf.setFont('helvetica', 'normal');
    pdf.text(alamatBawah, pageWidth / 2, 29, { align: 'center' });

    pdf.setDrawColor(0, 0, 0);
    pdf.setLineWidth(0.5);
    pdf.line(margin, 34, pageWidth - margin, 34);
  };

  const drawFooter = () => {
    const barY = pageHeight - 18;
    pdf.setDrawColor(0, 0, 0);
    pdf.setLineWidth(0.4);
    pdf.line(margin, barY, pageWidth - margin, barY);

    pdf.setTextColor(0, 0, 0);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(8);
    pdf.text(alamatBawah, pageWidth / 2, barY + 6, { align: 'center' });
  };

  return { pdf, pageWidth, pageHeight, margin, drawHeader, drawFooter };
}

async function exportFormulirPDF(submission, template, profil, kopLogoUrl) {
  const { pdf, pageWidth, pageHeight, margin, drawHeader, drawFooter } = createLetterheadPdf(profil, kopLogoUrl);

  await drawHeader();
  drawFooter();

  let y = 44;
  pdf.setTextColor(0, 0, 0);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(13);
  pdf.text(template.nama.toUpperCase(), pageWidth / 2, y, { align: 'center' });
  y += 6;
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(10);
  pdf.text(`No. ${submission.nomor}`, pageWidth / 2, y, { align: 'center' });
  y += 10;

  pdf.setFontSize(10);
  pdf.text(`Diajukan oleh: ${submission.submitted_by_nama}`, margin, y);
  pdf.text(`Tanggal: ${new Date(submission.created_at).toLocaleDateString('id-ID')}`, pageWidth - margin, y, { align: 'right' });
  y += 8;

  if (template.fields_schema.length > 0) {
    autoTable(pdf, {
      startY: y,
      margin: { left: margin, right: margin },
      body: template.fields_schema.map(f => [f.label, formatFieldValue(f, submission.data[f.id])]),
      styles: { fontSize: 10, cellPadding: 2 },
      columnStyles: { 0: { fontStyle: 'bold', cellWidth: 45 } },
      theme: 'plain',
    });
    y = pdf.lastAutoTable.finalY + 6;
  }

  if (template.has_table && submission.rows.length > 0) {
    autoTable(pdf, {
      startY: y,
      margin: { left: margin, right: margin },
      head: [['No', ...template.table_schema.map(c => c.label)]],
      body: submission.rows.map((row, idx) => [idx + 1, ...template.table_schema.map(c => formatFieldValue(c, row[c.id]))]),
      styles: { fontSize: 9, cellPadding: 2 },
      headStyles: { fillColor: [16, 128, 90], textColor: 255 },
    });
    y = pdf.lastAutoTable.finalY + 10;
  }

  if (submission.approvals.length > 0) {
    if (y > pageHeight - 70) { pdf.addPage(); await drawHeader(); drawFooter(); y = 44; }

    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(10);
    pdf.text('Persetujuan', margin, y);
    y += 6;

    const colWidth = (pageWidth - 2 * margin) / submission.approvals.length;
    const boxTop = y;
    const boxHeight = 38;

    for (let i = 0; i < submission.approvals.length; i++) {
      const a = submission.approvals[i];
      const x = margin + i * colWidth;

      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(9);
      pdf.text(a.label, x + colWidth / 2, boxTop, { align: 'center' });

      if (a.signature_data) {
        try {
          pdf.addImage(a.signature_data, 'PNG', x + colWidth / 2 - 20, boxTop + 4, 40, 20);
        } catch { /* ignore invalid signature image */ }
      } else {
        pdf.setDrawColor(180, 180, 180);
        pdf.line(x + 10, boxTop + boxHeight - 12, x + colWidth - 10, boxTop + boxHeight - 12);
      }

      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(9);
      pdf.text(a.approved_by_nama || '(...........................)', x + colWidth / 2, boxTop + boxHeight - 6, { align: 'center' });
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(8);
      pdf.text(a.approved_at ? new Date(a.approved_at).toLocaleDateString('id-ID') : '', x + colWidth / 2, boxTop + boxHeight, { align: 'center' });
    }
  }

  pdf.save(`formulir-${submission.nomor.replace(/\//g, '-')}.pdf`);
}

async function exportMasterDataPDF(template, records, profil, kopLogoUrl) {
  const { pdf, pageWidth, margin, drawHeader, drawFooter } = createLetterheadPdf(profil, kopLogoUrl);

  await drawHeader();
  drawFooter();

  let y = 44;
  pdf.setTextColor(0, 0, 0);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(13);
  pdf.text(template.nama.toUpperCase(), pageWidth / 2, y, { align: 'center' });
  y += 6;
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(9);
  if (template.deskripsi) {
    pdf.text(template.deskripsi, pageWidth / 2, y, { align: 'center' });
    y += 6;
  }
  pdf.text(`Dicetak: ${new Date().toLocaleString('id-ID')} — Total ${records.length} data`, pageWidth / 2, y, { align: 'center' });
  y += 8;

  const tableColumns = template.fields_schema.filter(f => f.is_table_column !== false);

  autoTable(pdf, {
    startY: y,
    margin: { left: margin, right: margin },
    head: [['No', ...tableColumns.map(f => f.label)]],
    body: records.map((r, idx) => [idx + 1, ...tableColumns.map(f => formatFieldValue(f, r.data[f.id]))]),
    styles: { fontSize: 9, cellPadding: 2 },
    headStyles: { fillColor: [16, 128, 90], textColor: 255 },
  });

  pdf.save(`${template.nama.toLowerCase().replace(/\s+/g, '-')}.pdf`);
}

// ─────────────────────────────────────────────────────────────────────────
// SIGNATURE PAD — komponen tanda tangan digital (canvas), pengganti TTD basah
// ─────────────────────────────────────────────────────────────────────────
function SignaturePad({ onChange }) {
  const canvasRef = useRef(null);
  const containerRef = useRef(null);
  const drawing = useRef(false);
  const lastPoint = useRef(null);
  const [empty, setEmpty] = useState(true);

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const resize = () => {
      const rect = container.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      const prev = canvas.width > 0 ? canvas.toDataURL('image/png') : null;

      canvas.width = Math.max(1, Math.round(rect.width * dpr));
      canvas.height = Math.max(1, Math.round(rect.height * dpr));
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;

      const ctx = canvas.getContext('2d');
      ctx.scale(dpr, dpr);

      if (prev) {
        const img = new Image();
        img.onload = () => ctx.drawImage(img, 0, 0, rect.width, rect.height);
        img.src = prev;
      }
    };

    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(container);
    return () => ro.disconnect();
  }, []);

  const getPos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    const point = e.touches ? e.touches[0] : e;
    return { x: point.clientX - rect.left, y: point.clientY - rect.top };
  };

  const start = (e) => {
    e.preventDefault();
    drawing.current = true;
    lastPoint.current = getPos(e);
  };

  const move = (e) => {
    if (!drawing.current) return;
    e.preventDefault();
    const ctx = canvasRef.current.getContext('2d');
    const pos = getPos(e);
    ctx.beginPath();
    ctx.moveTo(lastPoint.current.x, lastPoint.current.y);
    ctx.lineTo(pos.x, pos.y);
    ctx.strokeStyle = '#111827';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();
    lastPoint.current = pos;
    setEmpty(false);
  };

  const end = () => {
    if (!drawing.current) return;
    drawing.current = false;
    lastPoint.current = null;
    onChange(canvasRef.current.toDataURL('image/png'));
  };

  const clear = () => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
    setEmpty(true);
    onChange(null);
  };

  return (
    <div className="space-y-2">
      <div ref={containerRef} className="border-2 border-dashed rounded-lg dark:border-gray-600 bg-white h-40">
        <canvas
          ref={canvasRef}
          className="touch-none cursor-crosshair rounded-lg"
          onMouseDown={start}
          onMouseMove={move}
          onMouseUp={end}
          onMouseLeave={end}
          onTouchStart={start}
          onTouchMove={move}
          onTouchEnd={end}
        />
      </div>
      <div className="flex items-center justify-between">
        <p className="text-xs text-gray-400">{empty ? "Tanda tangan di area putih di atas" : "Tanda tangan tersimpan"}</p>
        <Button type="button" variant="outline" size="sm" onClick={clear} className="gap-1 text-xs h-7">
          <Eraser size={12} /> Hapus
        </Button>
      </div>
    </div>
  );
}

