import { useEffect, useState } from 'react';
import { API_BASE_URL } from '../config/api';
import { PERMISSIONS_MATRIX } from '../lib/permissionsMatrix';

/**
 * Hook untuk load permissions dari database berdasarkan role
 * Jika tidak ada di database, gunakan default dari PERMISSIONS_MATRIX
 */
export const useRolePermissions = (role, token) => {
  const [permissions, setPermissions] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!role || !token) {
      // Set default permissions dari local matrix jika tidak ada role/token
      setPermissions(PERMISSIONS_MATRIX[role] || {});
      setLoading(false);
      return;
    }

    const loadPermissions = async () => {
      try {
        const response = await fetch(`${API_BASE_URL}/api/role-permissions/${role}`, {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        });

        if (response.ok) {
          const data = await response.json();
          const dbPermissions = data.permissions || {};
          
          // Merge dengan local matrix untuk field yang tidak ada di DB
          const mergedPermissions = {
            ...PERMISSIONS_MATRIX[role] || {},
            ...dbPermissions
          };
          
          setPermissions(mergedPermissions);
        } else {
          // Fallback ke local PERMISSIONS_MATRIX jika API error
          setPermissions(PERMISSIONS_MATRIX[role] || {});
        }
      } catch (error) {
        console.warn(`Could not load permissions for ${role}:`, error);
        // Fallback ke local PERMISSIONS_MATRIX
        setPermissions(PERMISSIONS_MATRIX[role] || {});
      } finally {
        setLoading(false);
      }
    };

    loadPermissions();
  }, [role, token]);

  /**
   * Check if user can perform an action on a menu
   * @param {string} menuId - Menu identifier (e.g., 'warga', 'karyawan', 'finance')
   * @param {string} action - Action type: 'read', 'create', 'update', 'delete'
   * @returns {boolean}
   */
  const canPerform = (menuId, action = 'read') => {
    if (!permissions || !permissions[menuId]) {
      return false;
    }
    return permissions[menuId][action] === true;
  };

  return {
    permissions,
    loading,
    canRead: (menuId) => canPerform(menuId, 'read'),
    canCreate: (menuId) => canPerform(menuId, 'create'),
    canUpdate: (menuId) => canPerform(menuId, 'update'),
    canEdit: (menuId) => canPerform(menuId, 'update'),
    canDelete: (menuId) => canPerform(menuId, 'delete'),
  };
};
