import React from 'react';
import { Button } from '@/components/ui/button';
import { Edit, Trash2 } from 'lucide-react';
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from '@/components/ui/alert-dialog';

const formatRp = (val) => `Rp ${Number(val || 0).toLocaleString('id-ID', { maximumFractionDigits: 0 })}`;

export default function BudgetTemplateList({ data, onEdit, onDelete }) {
    return (
        <div className="overflow-x-auto rounded-md border shadow-sm">
            <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200">
                    <tr>
                        <th className="px-4 py-3 font-semibold">Pos Keuangan</th>
                        <th className="px-4 py-3 font-semibold text-right">Default Budget (Pagu)</th>
                        <th className="px-4 py-3 text-center font-semibold w-24">Aksi</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-[var(--rw-border)] dark:divide-gray-700 bg-[var(--rw-bg-card)] dark:bg-gray-900">
                    {data.length === 0 ? (
                        <tr><td colSpan={3} className="text-center py-8 text-gray-500 italic">Belum ada template budget.</td></tr>
                    ) : (
                        data.map((item) => (
                            <tr key={item.finance_category_id} className="hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-800 transition-colors">
                                <td className="px-4 py-3 font-medium text-gray-900 dark:text-gray-100">
                                    {item.category_name}
                                </td>
                                <td className="px-4 py-3 text-right font-mono text-gray-700 dark:text-gray-300">
                                    {formatRp(item.default_amount)}
                                </td>
                                <td className="px-4 py-3 text-center flex justify-center gap-1">
                                    <Button variant="ghost" size="icon" onClick={() => onEdit(item)} title="Edit">
                                        <Edit className="w-4 h-4 text-blue-600" />
                                    </Button>
                                    
                                    <AlertDialog>
                                        <AlertDialogTrigger asChild>
                                            <Button variant="ghost" size="icon" className="hover:bg-red-100 text-red-600" title="Hapus">
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </AlertDialogTrigger>
                                        <AlertDialogContent>
                                            <AlertDialogHeader>
                                                <AlertDialogTitle>Hapus Template?</AlertDialogTitle>
                                                <AlertDialogDescription>
                                                    Apakah Anda yakin ingin menghapus template <strong>{item.category_name}</strong> (Default: {formatRp(item.default_amount)})? 
                                                    Data yang sudah dihapus tidak dapat dikembalikan.
                                                </AlertDialogDescription>
                                            </AlertDialogHeader>
                                            <AlertDialogFooter>
                                                <AlertDialogCancel>Batal</AlertDialogCancel>
                                                <AlertDialogAction onClick={() => onDelete(item.id)} className="bg-red-600 hover:bg-red-700">
                                                    Hapus
                                                </AlertDialogAction>
                                            </AlertDialogFooter>
                                        </AlertDialogContent>
                                    </AlertDialog>
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
    );
}
