import React, { useRef, useState, useEffect } from 'react';
import { Play, Pause, Mic } from 'lucide-react';

const formatTime = (sec) => {
  if (!sec || !isFinite(sec)) return '00:00';
  const s = Math.floor(sec % 60).toString().padStart(2, '0');
  const m = Math.floor(sec / 60).toString().padStart(2, '0');
  return `${m}:${s}`;
};

/**
 * VoiceNotePlayer — pemutar voice note yang sudah tersimpan di server.
 * Tampilan mirip bubble voice note WhatsApp: tombol play/pause + progress bar + durasi.
 */
const VoiceNotePlayer = ({ src, durationHint, className = '' }) => {
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(durationHint || 0);

  useEffect(() => {
    const audio = audioRef.current;
    if (!audio) return;
    const onTime = () => setCurrentTime(audio.currentTime);
    const onLoaded = () => { if (isFinite(audio.duration)) setDuration(audio.duration); };
    const onEnd = () => { setIsPlaying(false); setCurrentTime(0); };
    audio.addEventListener('timeupdate', onTime);
    audio.addEventListener('loadedmetadata', onLoaded);
    audio.addEventListener('ended', onEnd);
    return () => {
      audio.removeEventListener('timeupdate', onTime);
      audio.removeEventListener('loadedmetadata', onLoaded);
      audio.removeEventListener('ended', onEnd);
    };
  }, []);

  const togglePlay = () => {
    if (!audioRef.current) return;
    if (isPlaying) audioRef.current.pause();
    else audioRef.current.play();
    setIsPlaying(p => !p);
  };

  const handleSeek = (e) => {
    if (!audioRef.current || !duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = (e.clientX - rect.left) / rect.width;
    audioRef.current.currentTime = ratio * duration;
  };

  const progressPct = duration ? Math.min(100, (currentTime / duration) * 100) : 0;

  if (!src) return null;

  return (
    <div className={`flex items-center gap-2.5 px-3 py-2 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 rounded-lg ${className}`}>
      <audio ref={audioRef} src={src} preload="metadata" className="hidden" />
      <button
        type="button"
        onClick={togglePlay}
        className="flex-shrink-0 w-8 h-8 rounded-full bg-emerald-500 hover:bg-emerald-600 text-white flex items-center justify-center"
      >
        {isPlaying ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4 ml-0.5" />}
      </button>
      <div className="flex-1 min-w-0">
        <div
          className="h-1.5 rounded-full bg-emerald-200 dark:bg-emerald-800 cursor-pointer overflow-hidden"
          onClick={handleSeek}
        >
          <div className="h-full bg-emerald-500 transition-all" style={{ width: `${progressPct}%` }} />
        </div>
        <div className="flex justify-between mt-1">
          <span className="text-[10px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1">
            <Mic className="w-2.5 h-2.5" /> Voice Note
          </span>
          <span className="text-[10px] text-emerald-600 dark:text-emerald-400 tabular-nums">
            {formatTime(isPlaying || currentTime > 0 ? currentTime : duration)}
          </span>
        </div>
      </div>
    </div>
  );
};

export default VoiceNotePlayer;
