import React, { useState, useEffect, useCallback, useRef } from 'react';
import { createPortal } from 'react-dom';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { vendorConfirm, vendorAlert } from './VendorConfirm';
import {
  Database, Download, Upload, Trash2, RefreshCw,
  AlertTriangle, CheckCircle2, ShieldAlert, Loader2,
  FileCode2, Plus, RotateCcw, ChevronDown, ChevronUp,
  HardDrive, Clock,
} from 'lucide-react';

const token = () => localStorage.getItem('vendor_token');
const hdrs = () => ({ Authorization: `Bearer ${token()}` });

function fmtSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
}

function fmtDate(iso) {
  try {
    return new Date(iso).toLocaleString('id-ID', {
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit',
    });
  } catch { return iso; }
}

export default function VendorDataManagement() {
  const [tables, setTables]           = useState([]);
  const [loadingTables, setLoadingTables] = useState(true);
  const [backups, setBackups]         = useState([]);
  const [loadingBackups, setLoadingBackups] = useState(true);
  const [selected, setSelected]       = useState(new Set());
  const [creating, setCreating]       = useState(false);
  const [uploading, setUploading]     = useState(false);
  const [restoringFile, setRestoringFile] = useState(null);
  const [restoreModal, setRestoreModal] = useState({ open: false, filename: null, mode: 'append' });
  const [deletingFile, setDeletingFile]   = useState(null);   // filename being deleted
  const [downloadingFile, setDownloadingFile] = useState(null);
  const [clearing, setClearing]       = useState(false);
  const [clearResult, setClearResult] = useState(null);
  const [showProtected, setShowProtected] = useState(false);
  const uploadRef = useRef(null);

  const loadTables = useCallback(async () => {
    setLoadingTables(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/data-management/tables`, { headers: hdrs() });
      if (!res.ok) throw new Error('Gagal memuat daftar tabel');
      setTables(await res.json());
    } catch (e) {
      toast.error(e.message);
    } finally {
      setLoadingTables(false);
    }
  }, []);

  const loadBackups = useCallback(async () => {
    setLoadingBackups(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/data-management/backup/list`, { headers: hdrs() });
      if (!res.ok) throw new Error('Gagal memuat daftar backup');
      setBackups(await res.json());
    } catch (e) {
      toast.error(e.message);
    } finally {
      setLoadingBackups(false);
    }
  }, []);

  useEffect(() => { loadTables(); loadBackups(); }, [loadTables, loadBackups]);

  const clearableTables = tables.filter(t => !t.protected);
  const protectedTables = tables.filter(t => t.protected);
  const totalRows = tables.reduce((s, t) => s + (t.row_count > 0 ? t.row_count : 0), 0);

  // ─── Backup: Create ──────────────────────────────────────────────────────
  const handleCreate = async () => {
    const ok = await vendorConfirm(
      `Buat backup baru dari seluruh database sekarang? File .sql akan disimpan di server dan dapat diunduh kapan saja.`,
      'Buat Backup Database'
    );
    if (!ok) return;
    setCreating(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/data-management/backup/create`, {
        method: 'POST', headers: hdrs(),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal membuat backup');
      toast.success(`Backup dibuat: ${data.filename} (${fmtSize(data.size)})`);
      await loadBackups();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setCreating(false);
    }
  };

  // ─── Backup: Upload ──────────────────────────────────────────────────────
  const handleUpload = async (file) => {
    if (!file) return;
    if (!file.name.endsWith('.sql')) { toast.error('Hanya file .sql yang diterima'); return; }
    setUploading(true);
    try {
      const form = new FormData();
      form.append('file', file);
      const res = await fetch(`${API_BASE_URL}/api/vendor/data-management/backup/upload`, {
        method: 'POST', headers: hdrs(), body: form,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal upload');
      toast.success(`File diunggah: ${data.filename}`);
      await loadBackups();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setUploading(false);
      if (uploadRef.current) uploadRef.current.value = '';
    }
  };

  // ─── Backup: Download ────────────────────────────────────────────────────
  const handleDownload = async (filename) => {
    setDownloadingFile(filename);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/vendor/data-management/backup/${encodeURIComponent(filename)}/download`,
        { headers: hdrs() }
      );
      if (!res.ok) { const d = await res.json(); throw new Error(d.detail || 'Gagal download'); }
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = filename; a.click();
      URL.revokeObjectURL(url);
    } catch (e) {
      toast.error(e.message);
    } finally {
      setDownloadingFile(null);
    }
  };

  // ─── Backup: Restore ─────────────────────────────────────────────────────
  const handleRestore = (filename) => {
    setRestoreModal({ open: true, filename, mode: 'append' });
  };

  const doRestore = async () => {
    const { filename, mode } = restoreModal;
    setRestoreModal({ open: false, filename: null, mode: 'append' });
    setRestoringFile(filename);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/vendor/data-management/backup/${encodeURIComponent(filename)}/restore?mode=${mode}`,
        { method: 'POST', headers: hdrs() }
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal restore');
      if (data.status === 'success') {
        const truncInfo = mode === 'replace' && data.truncated > 0
          ? ` (${data.truncated} tabel dikosongkan dulu)`
          : '';
        toast.success(`Restore selesai — ${data.executed} statement berhasil${truncInfo}`);
      } else {
        await vendorAlert(
          `Restore selesai dengan ${data.error_count} error dari ${data.executed + data.error_count} statement. Cek log untuk detail.`,
          'Restore Selesai (Sebagian)'
        );
      }
      await loadTables();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setRestoringFile(null);
    }
  };

  // ─── Backup: Delete file ─────────────────────────────────────────────────
  const handleDeleteFile = async (filename) => {
    const ok = await vendorConfirm(
      `Hapus file backup "${filename}" dari server? File yang dihapus tidak dapat dikembalikan.`,
      'Hapus File Backup'
    );
    if (!ok) return;
    setDeletingFile(filename);
    try {
      const res = await fetch(
        `${API_BASE_URL}/api/vendor/data-management/backup/${encodeURIComponent(filename)}`,
        { method: 'DELETE', headers: hdrs() }
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menghapus file');
      toast.success(`File "${filename}" dihapus`);
      await loadBackups();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setDeletingFile(null);
    }
  };

  // ─── Clear Tables ────────────────────────────────────────────────────────
  const toggleTable = (name) => {
    setSelected(prev => { const n = new Set(prev); n.has(name) ? n.delete(name) : n.add(name); return n; });
  };
  const toggleAll = () => {
    setSelected(selected.size === clearableTables.length ? new Set() : new Set(clearableTables.map(t => t.name)));
  };

  const handleClear = async () => {
    if (selected.size === 0) { toast.warning('Pilih minimal satu tabel'); return; }
    const names = [...selected];
    const ok = await vendorConfirm(
      `Hapus SEMUA data dari ${names.length} tabel terpilih? Aksi ini tidak dapat dibatalkan dan akan menghapus data cascading ke tabel referensi. Pastikan backup sudah dibuat.`,
      `Konfirmasi Hapus Data (${names.length} Tabel)`
    );
    if (!ok) return;
    setClearing(true);
    setClearResult(null);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/data-management/clear`, {
        method: 'POST',
        headers: { ...hdrs(), 'Content-Type': 'application/json' },
        body: JSON.stringify({ table_names: names }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menghapus data');
      setClearResult(data);
      setSelected(new Set());
      if (data.status === 'success') {
        toast.success(`${data.cleared.length} tabel berhasil dikosongkan`);
      } else {
        toast.warning(`${data.cleared.length} berhasil, ${data.errors.length} gagal`);
      }
      await loadTables();
    } catch (e) {
      toast.error(e.message);
    } finally {
      setClearing(false);
    }
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-gray-800 flex items-center justify-center shadow">
          <Database size={20} className="text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Data Management</h1>
          <p className="text-sm text-gray-500">Pemeliharaan database: backup, restore, dan hapus data</p>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-3 gap-3">
        <div className="bg-white rounded-xl border border-gray-200 px-4 py-3">
          <p className="text-xs text-gray-500">Total Tabel</p>
          <p className="text-2xl font-bold text-gray-800">{tables.length}</p>
        </div>
        <div className="bg-white rounded-xl border border-gray-200 px-4 py-3">
          <p className="text-xs text-gray-500">Total Data</p>
          <p className="text-2xl font-bold text-gray-800">{totalRows.toLocaleString('id-ID')}</p>
        </div>
        <div className="bg-white rounded-xl border border-gray-200 px-4 py-3">
          <p className="text-xs text-gray-500">File Backup</p>
          <p className="text-2xl font-bold text-gray-800">{backups.length}</p>
        </div>
      </div>

      {/* ── Backup & Restore ── */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        {/* Card header */}
        <div className="px-5 py-4 border-b border-gray-200 flex items-center justify-between gap-3 flex-wrap">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
              <HardDrive size={16} className="text-blue-600" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-gray-900">Backup &amp; Restore Database</h2>
              <p className="text-xs text-gray-400">Kelola file backup SQL — buat, upload, restore, dan hapus</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={loadBackups}
              className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400"
              title="Refresh daftar backup"
            >
              <RefreshCw size={14} className={loadingBackups ? 'animate-spin' : ''} />
            </button>
            {/* Upload */}
            <input ref={uploadRef} type="file" accept=".sql" className="hidden"
              onChange={e => handleUpload(e.target.files?.[0])} />
            <button
              onClick={() => uploadRef.current?.click()}
              disabled={uploading}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-gray-300 text-gray-600 text-xs font-medium hover:bg-gray-50 disabled:opacity-50 transition-colors"
            >
              {uploading ? <Loader2 size={12} className="animate-spin" /> : <Upload size={12} />}
              {uploading ? 'Mengunggah...' : 'Upload .sql'}
            </button>
            {/* Create */}
            <button
              onClick={handleCreate}
              disabled={creating}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-600 hover:bg-blue-700 text-white text-xs font-medium disabled:opacity-50 transition-colors"
            >
              {creating ? <Loader2 size={12} className="animate-spin" /> : <Plus size={12} />}
              {creating ? 'Membuat...' : 'Buat Backup Baru'}
            </button>
          </div>
        </div>

        {/* Backup file list */}
        {loadingBackups ? (
          <div className="flex items-center justify-center py-10">
            <Loader2 size={22} className="animate-spin text-gray-400" />
          </div>
        ) : backups.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-12 gap-2 text-gray-400">
            <HardDrive size={36} className="opacity-30" />
            <p className="text-sm">Belum ada file backup</p>
            <p className="text-xs">Klik &ldquo;Buat Backup Baru&rdquo; untuk membuat backup pertama</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {/* Column header */}
            <div className="grid grid-cols-[1fr_auto_auto_auto] items-center gap-3 px-5 py-2 bg-gray-50 text-xs font-semibold text-gray-400 uppercase">
              <span>Nama File</span>
              <span className="text-right w-20">Ukuran</span>
              <span className="text-right w-36">Dibuat</span>
              <span className="text-right w-32">Aksi</span>
            </div>

            {backups.map(b => {
              const isRestoring   = restoringFile === b.filename;
              const isDeleting    = deletingFile === b.filename;
              const isDownloading = downloadingFile === b.filename;
              return (
                <div key={b.filename}
                  className="grid grid-cols-[1fr_auto_auto_auto] items-center gap-3 px-5 py-3 hover:bg-gray-50 transition-colors">
                  {/* Filename */}
                  <div className="flex items-center gap-2 min-w-0">
                    <FileCode2 size={15} className="text-blue-400 flex-shrink-0" />
                    <span className="text-sm text-gray-700 truncate font-mono" title={b.filename}>
                      {b.filename}
                    </span>
                  </div>

                  {/* Size */}
                  <span className="text-xs text-gray-500 text-right w-20 flex-shrink-0">
                    {fmtSize(b.size)}
                  </span>

                  {/* Date */}
                  <span className="text-xs text-gray-400 text-right w-36 flex-shrink-0 flex items-center justify-end gap-1">
                    <Clock size={11} />
                    {fmtDate(b.created_at)}
                  </span>

                  {/* Actions */}
                  <div className="flex items-center gap-1.5 justify-end w-32 flex-shrink-0">
                    {/* Download */}
                    <button
                      onClick={() => handleDownload(b.filename)}
                      disabled={isDownloading || isRestoring || isDeleting}
                      title="Download file backup"
                      className="p-1.5 rounded-lg bg-blue-50 text-blue-600 hover:bg-blue-100 disabled:opacity-40 transition-colors"
                    >
                      {isDownloading
                        ? <Loader2 size={13} className="animate-spin" />
                        : <Download size={13} />}
                    </button>

                    {/* Restore */}
                    <button
                      onClick={() => handleRestore(b.filename)}
                      disabled={isRestoring || isDownloading || isDeleting}
                      title="Restore dari file ini"
                      className="p-1.5 rounded-lg bg-emerald-50 text-emerald-600 hover:bg-emerald-100 disabled:opacity-40 transition-colors"
                    >
                      {isRestoring
                        ? <Loader2 size={13} className="animate-spin" />
                        : <RotateCcw size={13} />}
                    </button>

                    {/* Delete */}
                    <button
                      onClick={() => handleDeleteFile(b.filename)}
                      disabled={isDeleting || isRestoring || isDownloading}
                      title="Hapus file backup"
                      className="p-1.5 rounded-lg bg-red-50 text-red-500 hover:bg-red-100 disabled:opacity-40 transition-colors"
                    >
                      {isDeleting
                        ? <Loader2 size={13} className="animate-spin" />
                        : <Trash2 size={13} />}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* Info footer */}
        <div className="px-5 py-2.5 bg-gray-50 border-t border-gray-100 text-xs text-gray-400 flex items-center gap-1.5">
          <AlertTriangle size={11} />
          Mode Append: data ditambahkan, duplikat dilewati. Mode Replace: tabel dikosongkan dulu lalu di-restore.
        </div>
      </div>

      {/* ── Restore Mode Modal ── */}
      {restoreModal.open && createPortal(
        <div className="fixed inset-0 z-[99999] flex items-center justify-center p-4"
          style={{ backdropFilter: 'blur(4px)', background: 'rgba(0,0,0,0.35)' }}>
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden">
            <div className="p-6">
              {/* Header */}
              <div className="flex items-start gap-3 mb-4">
                <div className="w-9 h-9 rounded-full bg-emerald-100 flex items-center justify-center flex-shrink-0">
                  <RotateCcw size={18} className="text-emerald-600" />
                </div>
                <div className="min-w-0">
                  <p className="font-bold text-gray-800 text-sm">Konfirmasi Restore</p>
                  <p className="text-xs text-gray-400 mt-0.5 font-mono truncate">{restoreModal.filename}</p>
                </div>
              </div>

              {/* Mode options */}
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Pilih mode restore:</p>
              <div className="space-y-2 mb-4">
                <label className={`flex items-start gap-3 p-3 rounded-xl border-2 cursor-pointer transition-colors ${
                  restoreModal.mode === 'append'
                    ? 'border-emerald-500 bg-emerald-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}>
                  <input
                    type="radio" name="restore_mode" value="append"
                    checked={restoreModal.mode === 'append'}
                    onChange={() => setRestoreModal(s => ({ ...s, mode: 'append' }))}
                    className="mt-0.5 flex-shrink-0"
                  />
                  <div>
                    <p className="text-sm font-semibold text-gray-800">Append — Tambah Data</p>
                    <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">
                      Tambahkan data baru ke tabel yang sudah ada. Data existing tidak berubah, duplikat dilewati secara otomatis.
                    </p>
                  </div>
                </label>

                <label className={`flex items-start gap-3 p-3 rounded-xl border-2 cursor-pointer transition-colors ${
                  restoreModal.mode === 'replace'
                    ? 'border-red-500 bg-red-50'
                    : 'border-gray-200 hover:border-gray-300'
                }`}>
                  <input
                    type="radio" name="restore_mode" value="replace"
                    checked={restoreModal.mode === 'replace'}
                    onChange={() => setRestoreModal(s => ({ ...s, mode: 'replace' }))}
                    className="mt-0.5 flex-shrink-0"
                  />
                  <div>
                    <p className="text-sm font-semibold text-gray-800">Replace — Ganti Data</p>
                    <p className="text-xs text-gray-500 mt-0.5 leading-relaxed">
                      Kosongkan tabel terkait terlebih dahulu, lalu restore dari backup.{' '}
                      <span className="font-semibold text-red-600">Semua data lama akan terhapus!</span>
                    </p>
                  </div>
                </label>
              </div>

              {/* Replace warning */}
              {restoreModal.mode === 'replace' && (
                <div className="flex items-center gap-2 px-3 py-2 bg-red-50 border border-red-200 rounded-lg text-xs text-red-700 mb-4">
                  <AlertTriangle size={12} className="flex-shrink-0" />
                  Data saat ini akan dihapus permanen sebelum restore. Pastikan sudah backup terbaru.
                </div>
              )}

              {/* Buttons */}
              <div className="flex gap-3">
                <button
                  onClick={() => setRestoreModal({ open: false, filename: null, mode: 'append' })}
                  className="flex-1 border border-gray-200 rounded-xl py-2.5 text-sm font-medium hover:bg-gray-50 text-gray-700 transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={doRestore}
                  className={`flex-1 text-white rounded-xl py-2.5 text-sm font-semibold transition-colors ${
                    restoreModal.mode === 'replace'
                      ? 'bg-red-600 hover:bg-red-700'
                      : 'bg-emerald-600 hover:bg-emerald-700'
                  }`}
                >
                  {restoreModal.mode === 'replace' ? 'Hapus & Restore' : 'Ya, Restore'}
                </button>
              </div>
            </div>
          </div>
        </div>,
      document.body
      )}

      {/* ── Clear Tables ── */}
      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        <div className="px-5 py-4 border-b border-gray-200 flex items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-red-100 rounded-lg flex items-center justify-center">
              <Trash2 size={16} className="text-red-600" />
            </div>
            <div>
              <h2 className="text-sm font-semibold text-gray-900">Hapus Data Tabel</h2>
              <p className="text-xs text-gray-400">Pilih tabel yang ingin dikosongkan (TRUNCATE CASCADE)</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={loadTables} className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400" title="Refresh">
              <RefreshCw size={14} className={loadingTables ? 'animate-spin' : ''} />
            </button>
            <button
              onClick={handleClear}
              disabled={clearing || selected.size === 0}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-red-600 hover:bg-red-700 text-white text-xs font-medium disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              {clearing ? <Loader2 size={12} className="animate-spin" /> : <Trash2 size={12} />}
              {clearing ? 'Menghapus...' : `Hapus Terpilih${selected.size > 0 ? ` (${selected.size})` : ''}`}
            </button>
          </div>
        </div>

        {/* Warning bar */}
        <div className="px-5 py-2.5 bg-red-50 border-b border-red-100 flex items-center gap-2 text-xs text-red-700">
          <ShieldAlert size={13} className="flex-shrink-0" />
          <span>
            <strong>Peringatan:</strong> Menghapus tabel tidak dapat dibatalkan. Data cascading ke tabel lain juga akan terhapus. Buat backup terlebih dahulu.
          </span>
        </div>

        {/* Select all bar */}
        {!loadingTables && clearableTables.length > 0 && (
          <div className="px-5 py-2 border-b border-gray-100 bg-gray-50">
            <label className="flex items-center gap-2 text-xs text-gray-600 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={selected.size === clearableTables.length && clearableTables.length > 0}
                onChange={toggleAll}
                className="rounded border-gray-300"
              />
              Pilih Semua ({clearableTables.length} tabel)
            </label>
          </div>
        )}

        {/* Table rows */}
        {loadingTables ? (
          <div className="flex items-center justify-center py-10">
            <Loader2 size={22} className="animate-spin text-gray-400" />
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {clearableTables.map(t => (
              <label key={t.name} className="flex items-center gap-3 px-5 py-2.5 hover:bg-gray-50 cursor-pointer">
                <input
                  type="checkbox"
                  checked={selected.has(t.name)}
                  onChange={() => toggleTable(t.name)}
                  className="rounded border-gray-300 flex-shrink-0"
                />
                <span className="flex-1 font-mono text-sm text-gray-700">{t.name}</span>
                <span className={`text-xs font-medium px-2 py-0.5 rounded-full ${
                  t.row_count === 0 ? 'bg-gray-100 text-gray-400'
                  : t.row_count > 1000 ? 'bg-red-100 text-red-700'
                  : 'bg-blue-100 text-blue-700'
                }`}>
                  {t.row_count < 0 ? 'error' : t.row_count.toLocaleString('id-ID')} baris
                </span>
              </label>
            ))}
          </div>
        )}

        {/* Protected tables */}
        {protectedTables.length > 0 && (
          <div className="border-t border-gray-200">
            <button
              onClick={() => setShowProtected(p => !p)}
              className="w-full flex items-center justify-between px-5 py-2.5 text-xs text-gray-400 hover:bg-gray-50 transition-colors"
            >
              <span className="flex items-center gap-1.5">
                <ShieldAlert size={12} />
                {protectedTables.length} tabel dilindungi (tidak dapat dihapus)
              </span>
              {showProtected ? <ChevronUp size={13} /> : <ChevronDown size={13} />}
            </button>
            {showProtected && (
              <div className="divide-y divide-gray-100 bg-gray-50/50">
                {protectedTables.map(t => (
                  <div key={t.name} className="flex items-center gap-3 px-5 py-2 opacity-60">
                    <input type="checkbox" disabled className="rounded border-gray-300" />
                    <span className="flex-1 font-mono text-sm text-gray-500">{t.name}</span>
                    <span className="text-xs text-gray-400 px-2 py-0.5 rounded-full bg-gray-100">
                      {t.row_count < 0 ? 'error' : t.row_count.toLocaleString('id-ID')} baris
                    </span>
                    <span className="text-xs bg-gray-200 text-gray-500 px-1.5 py-0.5 rounded">dilindungi</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Clear result */}
        {clearResult && (
          <div className={`border-t px-5 py-3 text-sm flex items-start gap-2 ${
            clearResult.status === 'success'
              ? 'bg-emerald-50 border-emerald-200 text-emerald-700'
              : 'bg-amber-50 border-amber-200 text-amber-700'
          }`}>
            {clearResult.status === 'success'
              ? <CheckCircle2 size={15} className="flex-shrink-0 mt-0.5" />
              : <AlertTriangle size={15} className="flex-shrink-0 mt-0.5" />}
            <div>
              <p className="font-medium">
                {clearResult.cleared.length} tabel berhasil dikosongkan
                {clearResult.errors?.length > 0 && `, ${clearResult.errors.length} gagal`}
              </p>
              {clearResult.cleared.length > 0 && (
                <p className="text-xs mt-0.5 opacity-80">{clearResult.cleared.join(', ')}</p>
              )}
              {clearResult.errors?.length > 0 && (
                <ul className="text-xs mt-1 space-y-0.5 opacity-80">
                  {clearResult.errors.map((e, i) => (
                    <li key={i}>• {e.table}: {e.error}</li>
                  ))}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
