// ====================================================
// UTILITIES
// ====================================================

const formatRupiah = (value) => {
  if (!value) return "";
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
};

const removeFormatting = (value) => {
  return value.replace(/\./g, "");
};

// ====================================================
// TARIF UMUM (SINGLE) SECTION
// ====================================================

function TarifUmumSection({ token }) {
  const [tarif, setTarif] = useState(null);
  const [nominal, setNominal] = useState("");
  const [aktif, setAktif] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showWarning, setShowWarning] = useState(false);
  const [pendingAktifState, setPendingAktifState] = useState(false);

  // Load tarif umum
  useEffect(() => {
    loadTarifUmum();
  }, []);

  const loadTarifUmum = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${API_BASE_URL}/api/tarif-ipl/single`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setTarif(data);
        setNominal(data.nominal.toString());
        setAktif(data.aktif);
      }
    } catch (err) {
      console.error("Error loading tarif umum:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleAktifChange = (newState) => {
    // If enabling SINGLE, show warning that CUSTOM will be deactivated
    if (newState && !aktif) {
      setShowWarning(true);
      setPendingAktifState(newState);
    } else {
      setAktif(newState);
    }
  };

  const handleConfirmAktif = () => {
    setAktif(pendingAktifState);
    setShowWarning(false);
  };

  const handleSave = async () => {
    // Validation: nominal bisa 0 (akan set status tidak aktif otomatis)
    // Hanya perlu ada input nominal
    if (nominal === "" || nominal === undefined) {
      toast.error("Nominal harus diisi");
      return;
    }

    // If nominal 0, force aktif = false
    const finalAktif = parseFloat(nominal) > 0 ? aktif : false;

    try {
      setIsSaving(true);
      const res = await fetch(`${API_BASE_URL}/api/tarif-ipl/single`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          tipe_tarif: "SINGLE",
          nominal: parseFloat(nominal),
          aktif: finalAktif,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        setTarif(data);
        setAktif(data.aktif); // Update UI status sesuai response
        toast.success("Tarif Umum berhasil disimpan");
      } else {
        const err = await res.json();
        toast.error(err.detail || "Gagal menyimpan tarif");
      }
    } catch (err) {
      console.error("Error saving tarif umum:", err);
      toast.error("Terjadi kesalahan");
    } finally {
      setIsSaving(false);
    }
  };

  if (loading) {
    return <div className="p-6 text-gray-500">Memuat...</div>;
  }

  return (
    <>
      <div className="bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-lg p-6 border border-[var(--rw-border)] dark:border-gray-700">
        <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
          💰 Tarif Umum (SINGLE)
        </h3>

        <div className="space-y-4">
          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Nominal IPL (Rp)
            </Label>
            <Input
              type="text"
              placeholder="0"
              value={formatRupiah(nominal)}
              onChange={(e) => setNominal(removeFormatting(e.target.value))}
              className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600"
            />
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="aktif-single"
              checked={aktif}
              onCheckedChange={handleAktifChange}
            />
            <Label
              htmlFor="aktif-single"
              className="text-sm font-medium text-gray-700 dark:text-gray-300 cursor-pointer"
            >
              Status Aktif
            </Label>
          </div>

          <Button
            onClick={handleSave}
            disabled={isSaving}
            className="w-full bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
          >
            {isSaving ? "Menyimpan..." : "💾 Simpan Tarif Umum"}
          </Button>
        </div>
      </div>

      {/* Warning Dialog */}
      <AlertDialog open={showWarning} onOpenChange={setShowWarning}>
        <AlertDialogContent className="bg-[var(--rw-bg-card)] dark:bg-gray-800">
          <AlertDialogHeader>
            <AlertDialogTitle className="dark:text-white">Aktifkan Tarif Umum?</AlertDialogTitle>
            <AlertDialogDescription className="dark:text-gray-400">
              Mengaktifkan Tarif Umum (SINGLE) akan otomatis menonaktifkan semua Tarif Khusus (CUSTOM) yang aktif. Lanjutkan?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:border-gray-600 dark:text-white">Batal</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmAktif}
              className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white"
            >
              Lanjutkan
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

// ====================================================
// TARIF KHUSUS (CUSTOM) SECTION
// ====================================================

function TarifKhususModal({ open, onOpenChange, tarif, rumahList, onSaved, token }) {
  const [form, setForm] = useState({
    rumah_id: "",
    nominal: "",
    aktif: true,
  });
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (tarif) {
      setForm({
        rumah_id: tarif.rumah_id,
        nominal: tarif.nominal.toString(),
        aktif: tarif.aktif,
      });
    } else {
      setForm({
        rumah_id: "",
        nominal: "",
        aktif: true,
      });
    }
  }, [tarif, open]);

  const handleSave = async () => {
    // Validation: hanya cek rumah_id untuk CREATE mode
    if (!tarif && !form.rumah_id) {
      toast.error("Pilih rumah terlebih dahulu");
      return;
    }

    if (!form.nominal || parseFloat(form.nominal) <= 0) {
      toast.error("Nominal harus lebih dari 0");
      return;
    }

    try {
      setLoading(true);
      const url = tarif
        ? `${API_BASE_URL}/api/tarif-ipl/custom/${tarif.id}`
        : `${API_BASE_URL}/api/tarif-ipl/custom`;

      const method = tarif ? "PUT" : "POST";

      const payload = tarif
        ? {
            nominal: parseFloat(form.nominal),
            aktif: form.aktif,
          }
        : {
            tipe_tarif: "CUSTOM",
            rumah_id: form.rumah_id,
            nominal: parseFloat(form.nominal),
            aktif: form.aktif,
          };

      console.log("Sending request:", { method, url, payload });

      const res = await fetch(url, {
        method: method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        toast.success(tarif ? "Tarif berhasil diupdate" : "Tarif berhasil ditambah");
        onSaved();
        onOpenChange(false);
      } else {
        try {
          const err = await res.json();
          toast.error(err.detail || "Gagal menyimpan tarif");
        } catch (parseErr) {
          toast.error(`Gagal menyimpan tarif (HTTP ${res.status})`);
        }
      }
    } catch (err) {
      console.error("Error saving tarif custom:", err);
      const errorMsg = err instanceof TypeError 
        ? "Tidak dapat terhubung ke server - pastikan backend berjalan"
        : err.message || "Gagal menyimpan tarif";
      toast.error("Terjadi kesalahan: " + errorMsg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md dark:bg-gray-800">
        <DialogHeader>
          <DialogTitle className="dark:text-white">
            {tarif ? "Edit Tarif Khusus" : "Tambah Tarif Khusus"}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Pilih Rumah / Warga {tarif && "(Tidak bisa diubah)"}
            </Label>
            {tarif ? (
              <div className="mt-2 p-2 bg-gray-100 dark:bg-gray-600 rounded border border-gray-300 dark:border-gray-500 text-gray-900 dark:text-white">
                {rumahList.find((r) => r.id === form.rumah_id)?.nama_lengkap ||
                  rumahList.find((r) => r.id === form.rumah_id)?.pemilik_sah ||
                  "Unknown"} ({rumahList.find((r) => r.id === form.rumah_id)?.blok_no})
              </div>
            ) : (
              <Select value={form.rumah_id} onValueChange={(val) => setForm({ ...form, rumah_id: val })}>
                <SelectTrigger className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600">
                  <SelectValue placeholder="Pilih rumah..." />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-700">
                  {rumahList.map((r) => (
                    <SelectItem key={r.id} value={r.id} className="dark:text-white">
                      {r.nama_lengkap || r.pemilik_sah || "Unknown"} ({r.blok_no})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </div>

          <div>
            <Label className="text-sm font-medium text-gray-700 dark:text-gray-300">
              Nominal IPL (Rp)
            </Label>
            <Input
              type="text"
              placeholder="0"
              value={formatRupiah(form.nominal)}
              onChange={(e) => setForm({ ...form, nominal: removeFormatting(e.target.value) })}
              className="mt-2 dark:bg-gray-700 dark:text-white dark:border-gray-600"
            />
          </div>

          <div className="flex items-center space-x-2">
            <Checkbox
              id="aktif-custom"
              checked={form.aktif}
              onCheckedChange={(val) => setForm({ ...form, aktif: val })}
            />
            <Label
              htmlFor="aktif-custom"
              className="text-sm font-medium text-gray-700 dark:text-gray-300 cursor-pointer"
            >
              Status Aktif
            </Label>
          </div>
        </div>

        <div className="flex gap-2 justify-end pt-4">
          <Button variant="outline" onClick={() => onOpenChange(false)} className="dark:border-gray-600">
            Batal
          </Button>
          <Button onClick={handleSave} disabled={loading} className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
            {loading ? "Menyimpan..." : "Simpan"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

