import React from 'react'
import { useCMS } from './cmsContent.jsx'

// Secondary testimonial avatar colors — cycle through these for visual variety
const AVATAR_COLORS = ['var(--ink-2)', 'var(--gold)', 'var(--coral)']

export default function Testimonials() {
  const c = useCMS('testimonials')
  const featured = c.featured || {}
  const items = c.items || []
  return (
    <section className="section" id="ulasan" style={{paddingTop: 100}}>
      <div className="container">
        <div className="section-head">
          <span className="kicker">{c.kicker}</span>
          <h2 dangerouslySetInnerHTML={{ __html: c.title_html }} />
          <p>{c.description}</p>
        </div>

        <div className="testi-wrap">
          <div className="testi big" style={{background:'var(--ink)', color:'var(--paper)', borderColor:'var(--ink)'}}>
            <blockquote style={{color:'var(--paper)'}} dangerouslySetInnerHTML={{ __html: featured.quote_html }} />
            <div className="who">
              <div className="avatar" style={{background:'var(--coral)'}}>{(featured.name || '?').charAt(0)}</div>
              <div>
                <div className="name" style={{color:'var(--paper)'}}>{featured.name}</div>
                <div className="role" style={{color:'rgba(250,247,239,0.55)'}}>{featured.role}</div>
              </div>
            </div>
          </div>

          <div style={{display:'flex', flexDirection:'column', gap:14}}>
            {items.map((t, i) => (
              <div key={i} className="testi">
                <blockquote dangerouslySetInnerHTML={{ __html: t.quote_html }} />
                <div className="who">
                  <div className="avatar" style={{background: AVATAR_COLORS[i % AVATAR_COLORS.length]}}>{(t.name || '?').charAt(0)}</div>
                  <div>
                    <div className="name">{t.name}</div>
                    <div className="role">{t.role}</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  )
}
