import React, { useState } from 'react';
import { ImageUploadZone } from './ImageGallery';
import { API_ENDPOINTS } from '@/config/api';

const EMPTY = {
  nama: '', kategori: '', deskripsi: '', alamat: '', telepon: '',
  whatsapp: '', email: '', website: '', jam_operasional: '', tags: '',
  nama_pemilik: '', no_rumah: '', foto_url: '',
  instagram: '', facebook: '', tiktok: '', twitter: '', youtube: '',
};

export default function ListingForm({ initial, categories, onSave, onAfterSave,onClose }) {
  const [form, setForm] = useState(initial ? { ...initial } : { ...EMPTY });
  const [saving, setSaving] = useState(false);
  // pendingImages: array of { file, url, name } for new uploads
  // or plain strings (existing image URLs) when editing
  const [pendingImages, setPendingImages] = useState(
    initial?.images ? initial.images.map(url => ({ url, name: '' })) : []
  );

  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const handleSave = async () => {
    if (!form.nama?.trim()) { alert('Nama wajib diisi'); return; }
    if (!form.kategori)     { alert('Kategori wajib dipilih'); return; }
    setSaving(true);
    try {
      const result = await onSave({ ...form, aktif: form.aktif ?? 1 });
      // Upload new image files (items with .file property = new uploads)
      const newFiles = pendingImages.filter(p => p.file).map(p => p.file);
      if (newFiles.length > 0 && result?.id) {
        await API_ENDPOINTS.uploadImages(result.id, newFiles);
      }
      // 🔥 TAMBAHAN PENTING
      if (onAfterSave) {
        await onAfterSave();
      } else {
        onClose();
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-lg">
        <div className="modal-header">
          <h2>{initial ? '✏️ Edit Listing' : '➕ Tambah Listing Baru'}</h2>
          <button className="btn-close" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          <div className="form-grid">
            {/* ── Info Dasar ── */}
            <div className="form-section-title">📋 Informasi Dasar</div>

            <div className="form-group full">
              <label className="form-label">Nama Usaha / Layanan <span className="req">*</span></label>
              <input
                className="form-control"
                value={form.nama || ''}
                onChange={e => set('nama', e.target.value)}
                placeholder="Cth: Warung Bu Siti"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Kategori <span className="req">*</span></label>
              <select
                className="form-control"
                value={form.kategori || ''}
                onChange={e => set('kategori', e.target.value)}
              >
                <option value="">-- Pilih Kategori --</option>
                {categories.map(c => (
                  <option key={c.id} value={c.nama}>{c.icon} {c.nama}</option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label">No. Rumah / Blok / Kantor</label>
              <input
                className="form-control"
                value={form.no_rumah || ''}
                onChange={e => set('no_rumah', e.target.value)}
                placeholder="Cth: A-12"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Nama Pemilik</label>
              <input
                className="form-control"
                value={form.nama_pemilik || ''}
                onChange={e => set('nama_pemilik', e.target.value)}
                placeholder="Nama lengkap pemilik"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Jam Operasional</label>
              <input
                className="form-control"
                value={form.jam_operasional || ''}
                onChange={e => set('jam_operasional', e.target.value)}
                placeholder="08:00 - 21:00"
              />
            </div>

            <div className="form-group full">
              <label className="form-label">Alamat</label>
              <input
                className="form-control"
                value={form.alamat || ''}
                onChange={e => set('alamat', e.target.value)}
                placeholder="Blok A No. 12, Perum Botanika Sriwidari"
              />
            </div>

            <div className="form-group full">
              <label className="form-label">Deskripsi</label>
              <textarea
                className="form-control"
                value={form.deskripsi || ''}
                onChange={e => set('deskripsi', e.target.value)}
                placeholder="Jelaskan usaha atau layanan secara singkat dan menarik..."
                rows={3}
              />
            </div>

            <div className="form-group full">
              <label className="form-label">Tags (pisah koma)</label>
              <input
                className="form-control"
                value={form.tags || ''}
                onChange={e => set('tags', e.target.value)}
                placeholder="makanan, nasi goreng, sunda, murah"
              />
            </div>

            {/* ── Kontak ── */}
            <div className="form-section-title">📞 Kontak</div>

            <div className="form-group">
              <label className="form-label">Telepon</label>
              <input
                className="form-control"
                value={form.telepon || ''}
                onChange={e => set('telepon', e.target.value)}
                placeholder="081234567890"
              />
            </div>

            <div className="form-group">
              <label className="form-label">WhatsApp</label>
              <input
                className="form-control"
                value={form.whatsapp || ''}
                onChange={e => set('whatsapp', e.target.value)}
                placeholder="6281234567890 (awali 62)"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Email</label>
              <input
                className="form-control"
                type="email"
                value={form.email || ''}
                onChange={e => set('email', e.target.value)}
                placeholder="email@contoh.com"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Website</label>
              <input
                className="form-control"
                value={form.website || ''}
                onChange={e => set('website', e.target.value)}
                placeholder="https://website.com"
              />
            </div>

            {/* ── Media Sosial ── */}
            <div className="form-section-title">📱 Media Sosial</div>

            <div className="form-group">
              <label className="form-label">Instagram</label>
              <input
                className="form-control"
                value={form.instagram || ''}
                onChange={e => set('instagram', e.target.value)}
                placeholder="@username"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Facebook</label>
              <input
                className="form-control"
                value={form.facebook || ''}
                onChange={e => set('facebook', e.target.value)}
                placeholder="Nama halaman / username"
              />
            </div>

            <div className="form-group">
              <label className="form-label">TikTok</label>
              <input
                className="form-control"
                value={form.tiktok || ''}
                onChange={e => set('tiktok', e.target.value)}
                placeholder="@username"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Twitter / X</label>
              <input
                className="form-control"
                value={form.twitter || ''}
                onChange={e => set('twitter', e.target.value)}
                placeholder="@username"
              />
            </div>

            <div className="form-group">
              <label className="form-label">YouTube</label>
              <input
                className="form-control"
                value={form.youtube || ''}
                onChange={e => set('youtube', e.target.value)}
                placeholder="Channel / URL"
              />
            </div>

            {/* ── Status — hanya tampil saat edit ── */}
            {initial && (
              <>
                <div className="form-section-title">⚙️ Status Listing</div>
                <div className="form-group full">
                  <label className="form-label">Status</label>
                  <div className="status-toggle-wrap">
                    <button
                      type="button"
                      className={`status-toggle-btn ${(form.aktif ?? 1) === 1 ? 'active' : ''}`}
                      onClick={() => set('aktif', 1)}
                    >
                      <span className="stb-dot" />
                      ✓ Aktif
                    </button>
                    <button
                      type="button"
                      className={`status-toggle-btn ${(form.aktif ?? 1) === 0 ? 'inactive' : ''}`}
                      onClick={() => set('aktif', 0)}
                    >
                      <span className="stb-dot" />
                      ✕ Nonaktif
                    </button>
                  </div>
                  <p className="status-hint">
                    {(form.aktif ?? 1) === 1
                      ? '✅ Listing ini tampil di direktori dan bisa ditemukan warga.'
                      : '⚠️ Listing ini disembunyikan dan tidak tampil di direktori.'}
                  </p>
                </div>
              </>
            )}
            
            {/* ── Foto Galeri (multi-image upload) ── */}
            <ImageUploadZone
              existingImages={initial?.images || []}
              onChange={setPendingImages}
            />
          </div>
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Batal</button>
          <button className="btn btn-primary" onClick={handleSave} disabled={saving}>
            {saving ? '⏳ Menyimpan...' : initial ? '💾 Simpan' : '➕ Tambah'}
          </button>
        </div>
      </div>
    </div>
  );
}
