import { useState, useEffect } from "react";

import { API_BASE_URL } from "@/config/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "@/components/ui/sonner";

export default function RekeningForm({ open, onOpenChange, rekening, onSaved }) {
  const { token, logout } = useAuth();
  const [form, setForm] = useState({
    kode_bank: "",
    nama_pemilik: "",
    email: "",
    nomor_rekening: "",
    kategori_iuran: "iuran_wajib",
    aktif: true,
  });

  useEffect(() => {
    if (rekening) {
      setForm(rekening);
    } else {
      setForm({
        kode_bank: "",
        nama_pemilik: "",
        email: "",
        nomor_rekening: "",
        kategori_iuran: "iuran_wajib",
        aktif: true,
      });
    }
  }, [rekening, open]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setForm((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleSave = async () => {
    if (!form.kode_bank || !form.nama_pemilik) {
      toast.error("Kode Bank dan Nama Pemilik harus diisi");
      return;
    }

    try {
      const method = form.id ? "PUT" : "POST";
      const url = form.id
        ? `${API_BASE_URL}/api/rekening/${form.id}`
        : `${API_BASE_URL}/api/rekening`;

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(form),
      });

      if (res.status === 401) {
        logout();
        return;
      }

      toast.success(form.id ? "Rekening berhasil diperbarui" : "Rekening berhasil ditambahkan");
      onOpenChange(false);
      onSaved?.();
    } catch (err) {
      console.error("Gagal simpan rekening", err);
      toast.error("Gagal menyimpan rekening");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl overflow-y-auto dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>{form.id ? "Edit Rekening" : "Tambah Rekening Baru"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* KODE BANK | NAMA PEMILIK */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Kode Bank</label>
              <Input
                name="kode_bank"
                value={form.kode_bank}
                onChange={handleChange}
                placeholder="PT. BANK CENTRAL ASIA TBK."
                className="mt-1 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
              />
            </div>
            <div>
              <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Nama Pemilik</label>
              <Input
                name="nama_pemilik"
                value={form.nama_pemilik}
                onChange={handleChange}
                placeholder="PT. Nama Perusahaan"
                className="mt-1 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
              />
            </div>
          </div>

          {/* EMAIL */}
          <div>
            <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Email</label>
            <Input
              name="email"
              type="email"
              value={form.email}
              onChange={handleChange}
              placeholder="email@example.com"
              className="mt-1 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
            />
          </div>

          {/* NOMOR REKENING */}
          <div>
            <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Nomor Rekening</label>
            <Input
              name="nomor_rekening"
              value={form.nomor_rekening}
              onChange={handleChange}
              placeholder="1234567890"
              className="mt-1 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
            />
          </div>

          {/* KATEGORI IURAN */}
          <div>
            <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Rekening Kategori Iuran Wajib</label>
            <select
              name="kategori_iuran"
              value={form.kategori_iuran}
              onChange={handleChange}
              className="w-full p-2 mt-1 border rounded-md dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 bg-[var(--rw-bg-card-alt)]"
            >
              <option value="iuran_wajib">Iuran Wajib</option>
              <option value="iuran_sukarela">Iuran Sukarela</option>
              <option value="dana_sosial">Dana Sosial</option>
            </select>
          </div>

          {/* AKTIF */}
          <div>
            <label className="text-xs font-semibold text-gray-600 dark:text-gray-400">Status Aktif</label>
            <div className="flex items-center gap-2 mt-2">
              <input
                type="checkbox"
                name="aktif"
                checked={form.aktif}
                onChange={handleChange}
                className="h-4 w-4 dark:accent-cyan-500"
              />
              <span className="text-sm dark:text-gray-300">
                {form.aktif ? "✓ Aktif" : "✗ Tidak Aktif"}
              </span>
            </div>
          </div>
        </div>

        {/* BUTTONS */}
        <div className="flex justify-end gap-3 pt-4 border-t dark:border-gray-700">
          <Button variant="outline" onClick={() => onOpenChange(false)} className="dark:border-gray-700 dark:text-gray-200">
            Batal
          </Button>
          <Button onClick={handleSave} className="bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white">
            Simpan
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}
