import React, { useState } from "react";
import { useTenant } from "../contexts/TenantContext";
import { Building2, ChevronDown, Check, LogOut } from "lucide-react";

const typeBadge = (type) => {
  const map = { RT: "bg-blue-100 text-blue-700", RW: "bg-purple-100 text-purple-700", Kelurahan: "bg-orange-100 text-orange-700" };
  return <span className={`text-xs px-1.5 py-0.5 rounded font-semibold ${map[type] || "bg-gray-100"}`}>{type}</span>;
};

export default function TenantSwitcher() {
  const { currentTenant, tenantList, switchTenant, clearTenant, isVendorAdmin } = useTenant();
  const [open, setOpen] = useState(false);

  if (!isVendorAdmin) return null;

  return (
    <div className="relative">
      <button
        onClick={() => setOpen(o => !o)}
        className="flex items-center gap-2 px-3 py-1.5 rounded-xl border border-[var(--rw-border)] dark:border-gray-600 bg-[var(--rw-bg-card)] dark:bg-gray-800 hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 text-sm transition-colors max-w-[220px]"
      >
        <Building2 size={15} className="text-cyan-500 flex-shrink-0" />
        <span className="truncate text-gray-700 dark:text-gray-200 font-medium">
          {currentTenant ? currentTenant.name : "Pilih Tenant"}
        </span>
        {currentTenant && typeBadge(currentTenant.tenant_type)}
        <ChevronDown size={13} className={`text-gray-400 flex-shrink-0 transition-transform ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
          <div className="absolute top-full mt-1 right-0 z-50 w-72 bg-[var(--rw-bg-card)] dark:bg-gray-800 rounded-2xl shadow-xl border border-[var(--rw-border)] dark:border-gray-700 overflow-hidden">
            <div className="p-3 border-b dark:border-gray-700">
              <p className="text-xs font-medium text-gray-500 uppercase">Pilih Tenant</p>
            </div>
            <div className="max-h-72 overflow-y-auto">
              {tenantList.length === 0 && (
                <p className="px-4 py-3 text-sm text-gray-400 text-center">Belum ada tenant</p>
              )}
              {tenantList.map(t => (
                <button key={t.id}
                  onClick={() => { switchTenant(t); setOpen(false); }}
                  className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-[var(--rw-bg-card-alt)] dark:hover:bg-gray-700 transition-colors">
                  <div className="w-8 h-8 rounded-lg bg-cyan-100 dark:bg-cyan-900/30 flex items-center justify-center flex-shrink-0">
                    <Building2 size={14} className="text-cyan-600" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-800 dark:text-white truncate">{t.name}</p>
                    <div className="flex items-center gap-1 mt-0.5">
                      {typeBadge(t.tenant_type)}
                      <span className={`text-xs ${t.status === "active" ? "text-green-500" : "text-red-400"}`}>
                        • {t.status}
                      </span>
                    </div>
                  </div>
                  {currentTenant?.id === t.id && <Check size={14} className="text-cyan-500 flex-shrink-0" />}
                </button>
              ))}
            </div>
            {currentTenant && (
              <div className="border-t dark:border-gray-700 p-2">
                <button onClick={() => { clearTenant(); setOpen(false); }}
                  className="w-full flex items-center gap-2 px-3 py-2 text-sm text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl">
                  <LogOut size={13} /> Keluar dari tenant
                </button>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}
