import React, { useState, useEffect, useRef } from 'react';
import { API_BASE_URL } from '@/config/api';
import { toast } from '@/components/ui/sonner';
import { vendorConfirm } from './VendorConfirm';
import VendorThemeSettings from './VendorThemeSettings';
import VendorLoginLayoutSettings from './VendorLoginLayoutSettings';
import {
  Settings, Save, Upload, RefreshCw, Loader2,
  Image, AppWindow, Tag, FileText, Hash,
  Twitter, Facebook, Youtube, Instagram, Music2, MessageCircle, CreditCard, Phone,
  Palette, LayoutGrid, Headset, HelpCircle, MessageSquare,
} from 'lucide-react';

// Preset tema widget Support Chat — nilai id harus sama dengan yang
// divalidasi backend (app_settings.py) dan dibaca SupportChatButton.jsx.
const SUPPORT_THEMES = [
  { id: 'green', label: 'Hijau', color: '#16a34a' },
  { id: 'blue',  label: 'Biru',  color: '#2563eb' },
  { id: 'dark',  label: 'Gelap', color: '#1f2937' },
];

const SUPPORT_ICONS = [
  { id: 'message-circle', label: 'Bulat',   Icon: MessageCircle },
  { id: 'headset',        label: 'Headset', Icon: Headset },
  { id: 'help-circle',    label: 'Tanya',   Icon: HelpCircle },
  { id: 'message-square', label: 'Kotak',   Icon: MessageSquare },
];

const token = () => localStorage.getItem('vendor_token');
const hdrs  = () => ({ Authorization: `Bearer ${token()}` });

const resolveUrl = (url) => {
  if (!url) return null;
  if (url.startsWith('http')) return url;
  return `${API_BASE_URL}${url}`;
};

const Field = ({ label, icon: Icon, children }) => (
  <div>
    <label className="flex items-center gap-1.5 text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1.5">
      <Icon size={12} />
      {label}
    </label>
    {children}
  </div>
);

export default function VendorSettings() {
  const [form, setForm]             = useState({
    app_name: '', app_version: '', app_title: '', app_description: '',
    social_twitter: '', social_facebook: '', social_youtube: '',
    social_tiktok: '', social_discord: '', social_instagram: '',
    social_twitter_enabled: true, social_facebook_enabled: true, social_youtube_enabled: true,
    social_tiktok_enabled: true, social_discord_enabled: true, social_instagram_enabled: true,
    kelurahan_billing_enabled: true,
    support_default_whatsapp: '',
    support_widget_theme: 'green',
    support_widget_color: '',
    support_widget_icon: 'message-circle',
    support_widget_position: 'left',
  });
  const [logoUrl, setLogoUrl]       = useState(null);
  const [kopLogoUrl, setKopLogoUrl] = useState(null);
  const [loading, setLoading]       = useState(true);
  const [saving, setSaving]         = useState(false);
  const [uploading, setUploading]       = useState(false);
  const [kopUploading, setKopUploading] = useState(false);
  const [logoPreview, setLogoPreview]       = useState(null);
  const [kopLogoPreview, setKopLogoPreview] = useState(null);
  const uploadRef    = useRef(null);
  const kopUploadRef = useRef(null);

  const activeThemeColor =
    (SUPPORT_THEMES.find(t => t.id === form.support_widget_theme) || SUPPORT_THEMES[0]).color;

  const load = async () => {
    setLoading(true);
    try {
      const res  = await fetch(`${API_BASE_URL}/api/vendor/app-settings`, { headers: hdrs() });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal memuat');
      setForm({
        app_name:        data.app_name        || '',
        app_version:     data.app_version     || '',
        app_title:       data.app_title       || '',
        app_description: data.app_description || '',
        social_twitter:  data.social_twitter  || '',
        social_facebook: data.social_facebook || '',
        social_youtube:  data.social_youtube  || '',
        social_tiktok:    data.social_tiktok    || '',
        social_discord:   data.social_discord   || '',
        social_instagram: data.social_instagram || '',
        social_twitter_enabled:  data.social_twitter_enabled  !== false,
        social_facebook_enabled: data.social_facebook_enabled !== false,
        social_youtube_enabled:  data.social_youtube_enabled  !== false,
        social_tiktok_enabled:    data.social_tiktok_enabled    !== false,
        social_discord_enabled:   data.social_discord_enabled   !== false,
        social_instagram_enabled: data.social_instagram_enabled !== false,
        kelurahan_billing_enabled: data.kelurahan_billing_enabled !== false,
        support_default_whatsapp: data.support_default_whatsapp || '',
        support_widget_theme:    data.support_widget_theme    || 'green',
        support_widget_color:    data.support_widget_color    || '',
        support_widget_icon:     data.support_widget_icon     || 'message-circle',
        support_widget_position: data.support_widget_position || 'left',
      });
      const ts = Date.now();
      setLogoUrl(data.logo_url    ? resolveUrl(data.logo_url)    + `?t=${ts}` : null);
      setKopLogoUrl(data.kop_logo_url ? resolveUrl(data.kop_logo_url) + `?t=${ts}` : null);
    } catch (e) {
      toast.error(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const handleSave = async () => {
    if (!form.app_name.trim() || !form.app_title.trim()) {
      toast.error('Nama Aplikasi dan Judul wajib diisi');
      return;
    }
    setSaving(true);
    try {
      const res = await fetch(`${API_BASE_URL}/api/vendor/app-settings`, {
        method:  'PUT',
        headers: { ...hdrs(), 'Content-Type': 'application/json' },
        body:    JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal menyimpan');
      toast.success('Pengaturan berhasil disimpan');
    } catch (e) {
      toast.error(e.message);
    } finally {
      setSaving(false);
    }
  };

  const handleLogoSelect = (file) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berformat gambar'); return; }
    if (file.size > 5 * 1024 * 1024)    { toast.error('Ukuran file maks 5 MB'); return; }
    setLogoPreview(URL.createObjectURL(file));
  };

  const handleLogoUpload = async () => {
    if (!uploadRef.current?.files?.[0]) return;
    const ok = await vendorConfirm('Upload logo baru? Logo lama akan diganti.', 'Upload Logo');
    if (!ok) return;
    setUploading(true);
    try {
      const form = new FormData();
      form.append('file', uploadRef.current.files[0]);
      const res  = await fetch(`${API_BASE_URL}/api/vendor/app-settings/logo`, {
        method: 'POST', headers: hdrs(), body: form,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal upload');
      setLogoUrl(resolveUrl(data.logo_url) + `?t=${Date.now()}`);
      setLogoPreview(null);
      if (uploadRef.current) uploadRef.current.value = '';
      toast.success('Logo berhasil diperbarui');
    } catch (e) {
      toast.error(e.message);
    } finally {
      setUploading(false);
    }
  };

  const handleKopLogoSelect = (file) => {
    if (!file) return;
    if (!file.type.startsWith('image/')) { toast.error('File harus berformat gambar'); return; }
    if (file.size > 5 * 1024 * 1024)    { toast.error('Ukuran file maks 5 MB'); return; }
    setKopLogoPreview(URL.createObjectURL(file));
  };

  const handleKopLogoUpload = async () => {
    if (!kopUploadRef.current?.files?.[0]) return;
    const ok = await vendorConfirm('Upload logo kop surat baru? Logo lama akan diganti.', 'Upload Logo Kop Surat');
    if (!ok) return;
    setKopUploading(true);
    try {
      const form = new FormData();
      form.append('file', kopUploadRef.current.files[0]);
      const res  = await fetch(`${API_BASE_URL}/api/vendor/app-settings/kop-logo`, {
        method: 'POST', headers: hdrs(), body: form,
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.detail || 'Gagal upload');
      setKopLogoUrl(resolveUrl(data.kop_logo_url) + `?t=${Date.now()}`);
      setKopLogoPreview(null);
      if (kopUploadRef.current) kopUploadRef.current.value = '';
      toast.success('Logo kop surat berhasil diperbarui');
    } catch (e) {
      toast.error(e.message);
    } finally {
      setKopUploading(false);
    }
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-xl bg-gray-800 flex items-center justify-center shadow">
          <Settings size={20} className="text-white" />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Settings</h1>
          <p className="text-sm text-gray-500">Konfigurasi identitas dan tampilan aplikasi</p>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center py-20">
          <Loader2 size={28} className="animate-spin text-gray-400" />
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">

          {/* ── Logo ── */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 flex flex-col gap-4">
            <h2 className="text-sm font-semibold text-gray-800 flex items-center gap-2">
              <Image size={15} className="text-[#ed6f5c]" /> Logo Aplikasi
            </h2>

            {/* Preview */}
            <div className="flex flex-col items-center gap-3">
              <div className="w-32 h-32 rounded-2xl border-2 border-dashed border-gray-200 flex items-center justify-center bg-gray-50 overflow-hidden">
                {logoPreview || logoUrl ? (
                  <img
                    src={logoPreview || logoUrl}
                    alt="Logo preview"
                    className="w-full h-full object-contain p-2"
                  />
                ) : (
                  <div className="text-center">
                    <Image size={32} className="text-gray-300 mx-auto mb-1" />
                    <p className="text-xs text-gray-400">Belum ada logo</p>
                  </div>
                )}
              </div>
              <p className="text-xs text-gray-400 text-center">PNG/JPG/WEBP/SVG · maks 5 MB</p>
            </div>

            {/* Upload controls */}
            <input
              ref={uploadRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={e => handleLogoSelect(e.target.files?.[0])}
            />
            {logoPreview ? (
              <div className="flex gap-2">
                <button
                  onClick={() => { setLogoPreview(null); if (uploadRef.current) uploadRef.current.value = ''; }}
                  className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50 transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={handleLogoUpload}
                  disabled={uploading}
                  className="flex-1 py-2 rounded-lg bg-[#ed6f5c] hover:bg-[#e05544] text-white text-sm font-medium flex items-center justify-center gap-1.5 disabled:opacity-50 transition-colors"
                >
                  {uploading ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />}
                  {uploading ? 'Mengupload...' : 'Simpan Logo'}
                </button>
              </div>
            ) : (
              <button
                onClick={() => uploadRef.current?.click()}
                className="w-full py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50 transition-colors flex items-center justify-center gap-2"
              >
                <Upload size={14} /> Pilih File Logo
              </button>
            )}
          </div>

          {/* ── Logo Kop Surat ── */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 flex flex-col gap-4">
            <h2 className="text-sm font-semibold text-gray-800 flex items-center gap-2">
              <Image size={15} className="text-indigo-500" /> Logo Kop Surat
            </h2>
            <p className="text-xs text-gray-400 -mt-2">Digunakan pada kwitansi IPL, laporan keuangan, dan surat resmi</p>

            {/* Preview */}
            <div className="flex flex-col items-center gap-3">
              <div className="w-32 h-32 rounded-2xl border-2 border-dashed border-gray-200 flex items-center justify-center bg-gray-50 overflow-hidden">
                {kopLogoPreview || kopLogoUrl ? (
                  <img
                    src={kopLogoPreview || kopLogoUrl}
                    alt="Kop logo preview"
                    className="w-full h-full object-contain p-2"
                  />
                ) : (
                  <div className="text-center">
                    <Image size={32} className="text-gray-300 mx-auto mb-1" />
                    <p className="text-xs text-gray-400">Belum ada logo</p>
                  </div>
                )}
              </div>
              <p className="text-xs text-gray-400 text-center">PNG/JPG/WEBP/SVG · maks 5 MB</p>
            </div>

            {/* Upload controls */}
            <input
              ref={kopUploadRef}
              type="file"
              accept="image/*"
              className="hidden"
              onChange={e => handleKopLogoSelect(e.target.files?.[0])}
            />
            {kopLogoPreview ? (
              <div className="flex gap-2">
                <button
                  onClick={() => { setKopLogoPreview(null); if (kopUploadRef.current) kopUploadRef.current.value = ''; }}
                  className="flex-1 py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50 transition-colors"
                >
                  Batal
                </button>
                <button
                  onClick={handleKopLogoUpload}
                  disabled={kopUploading}
                  className="flex-1 py-2 rounded-lg bg-indigo-500 hover:bg-indigo-600 text-white text-sm font-medium flex items-center justify-center gap-1.5 disabled:opacity-50 transition-colors"
                >
                  {kopUploading ? <Loader2 size={13} className="animate-spin" /> : <Upload size={13} />}
                  {kopUploading ? 'Mengupload...' : 'Simpan Logo'}
                </button>
              </div>
            ) : (
              <button
                onClick={() => kopUploadRef.current?.click()}
                className="w-full py-2 rounded-lg border border-gray-200 text-sm text-gray-600 hover:bg-gray-50 transition-colors flex items-center justify-center gap-2"
              >
                <Upload size={14} /> Pilih File Logo Kop
              </button>
            )}
          </div>

          {/* ── Parameter Aplikasi ── */}
          <div className="bg-white rounded-xl border border-gray-200 p-5 space-y-4">
            <div className="flex items-center justify-between mb-1">
              <h2 className="text-sm font-semibold text-gray-800 flex items-center gap-2">
                <AppWindow size={15} className="text-[#ed6f5c]" /> Parameter Aplikasi
              </h2>
              <button onClick={load} className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400" title="Refresh">
                <RefreshCw size={13} />
              </button>
            </div>

            <Field label="Nama Aplikasi" icon={Tag}>
              <input
                value={form.app_name}
                onChange={e => setForm(s => ({ ...s, app_name: e.target.value }))}
                placeholder="contoh: Ruang Warga"
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
              />
            </Field>

            <Field label="Versi Aplikasi" icon={Hash}>
              <input
                value={form.app_version}
                onChange={e => setForm(s => ({ ...s, app_version: e.target.value }))}
                placeholder="contoh: 2.4"
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
              />
            </Field>

            <Field label="Judul Halaman (Browser Title)" icon={AppWindow}>
              <input
                value={form.app_title}
                onChange={e => setForm(s => ({ ...s, app_title: e.target.value }))}
                placeholder="contoh: Ruang Warga App"
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
              />
              <p className="text-xs text-gray-400 mt-1">Tampil di tab browser dan halaman login</p>
            </Field>

            <Field label="Deskripsi Aplikasi" icon={FileText}>
              <textarea
                value={form.app_description}
                onChange={e => setForm(s => ({ ...s, app_description: e.target.value }))}
                placeholder="contoh: Solusi Terintegrasi untuk RT, RW, dan Kelurahan"
                rows={3}
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c] resize-none"
              />
              <p className="text-xs text-gray-400 mt-1">Tampil di halaman login aplikasi</p>
            </Field>

            <Field label="No. WhatsApp Support Default" icon={Phone}>
              <input
                value={form.support_default_whatsapp}
                onChange={e => setForm(s => ({ ...s, support_default_whatsapp: e.target.value }))}
                placeholder="contoh: 081234567890"
                className="w-full px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
              />
              <p className="text-xs text-gray-400 mt-1">Dipakai untuk tombol "Chat tim kami" &amp; "Jadwalkan demo" di landing page publik</p>
            </Field>

            <div className="pt-2 border-t border-gray-100">
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3 mt-3">
                Media Sosial
              </p>
              <p className="text-xs text-gray-400 -mt-2 mb-3">
                Tampil sebagai ikon di halaman login. Kosongkan kalau tidak ingin ditampilkan.
              </p>
              <div className="space-y-3">
                <Field label="Twitter / X" icon={Twitter}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_twitter}
                      onChange={e => setForm(s => ({ ...s, social_twitter: e.target.value }))}
                      placeholder="https://x.com/namaanda"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_twitter_enabled}
                        onChange={e => setForm(s => ({ ...s, social_twitter_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
                <Field label="Facebook" icon={Facebook}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_facebook}
                      onChange={e => setForm(s => ({ ...s, social_facebook: e.target.value }))}
                      placeholder="https://facebook.com/namaanda"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_facebook_enabled}
                        onChange={e => setForm(s => ({ ...s, social_facebook_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
                <Field label="YouTube" icon={Youtube}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_youtube}
                      onChange={e => setForm(s => ({ ...s, social_youtube: e.target.value }))}
                      placeholder="https://youtube.com/@namaanda"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_youtube_enabled}
                        onChange={e => setForm(s => ({ ...s, social_youtube_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
                <Field label="Instagram" icon={Instagram}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_instagram}
                      onChange={e => setForm(s => ({ ...s, social_instagram: e.target.value }))}
                      placeholder="https://instagram.com/namaanda"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_instagram_enabled}
                        onChange={e => setForm(s => ({ ...s, social_instagram_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
                <Field label="TikTok" icon={Music2}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_tiktok}
                      onChange={e => setForm(s => ({ ...s, social_tiktok: e.target.value }))}
                      placeholder="https://tiktok.com/@namaanda"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_tiktok_enabled}
                        onChange={e => setForm(s => ({ ...s, social_tiktok_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
                <Field label="Discord" icon={MessageCircle}>
                  <div className="flex items-center gap-2">
                    <input
                      value={form.social_discord}
                      onChange={e => setForm(s => ({ ...s, social_discord: e.target.value }))}
                      placeholder="https://discord.gg/kodeundangan"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30 focus:border-[#ed6f5c]"
                    />
                    <label className="flex items-center gap-1.5 text-xs text-gray-500 whitespace-nowrap cursor-pointer">
                      <input
                        type="checkbox"
                        checked={form.social_discord_enabled}
                        onChange={e => setForm(s => ({ ...s, social_discord_enabled: e.target.checked }))}
                        className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                      />
                      Aktif
                    </label>
                  </div>
                </Field>
              </div>
              <p className="text-[11px] text-gray-400 mt-2">
                Ikon hanya tampil di login kalau link diisi <strong>dan</strong> centang "Aktif" dinyalakan.
                Bisa juga sementara disembunyikan dengan mematikan "Aktif" tanpa perlu hapus link-nya.
              </p>
            </div>

            <div className="pt-2 border-t border-gray-100">
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3 mt-3">
                Menu Kelurahan
              </p>
              <Field label="Billing" icon={CreditCard}>
                <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.kelurahan_billing_enabled}
                    onChange={e => setForm(s => ({ ...s, kelurahan_billing_enabled: e.target.checked }))}
                    className="rounded border-gray-300 text-[#ed6f5c] focus:ring-[#ed6f5c]/30"
                  />
                  Tampilkan menu "Billing" di sidebar Kelurahan
                </label>
                <p className="text-[11px] text-gray-400 mt-1">
                  Matikan kalau fitur billing tingkat Kelurahan belum relevan untuk instansi ini.
                </p>
              </Field>
            </div>

            <div className="pt-2 border-t border-gray-100">
              <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1 mt-3">
                Widget Support Chat
              </p>
              <p className="text-xs text-gray-400 mb-3">
                Tampilan tombol chat support yang muncul di dashboard RT/RW/Kelurahan.
              </p>

              {/* Tema */}
              <Field label="Tema Warna" icon={Palette}>
                <div className="grid grid-cols-3 gap-2">
                  {SUPPORT_THEMES.map(t => (
                    <button key={t.id} type="button"
                      onClick={() => setForm(s => ({ ...s, support_widget_theme: t.id }))}
                      className={`py-2 rounded-xl border-2 text-xs font-semibold transition-all flex items-center justify-center gap-1.5 ${
                        form.support_widget_theme === t.id
                          ? 'border-[#ed6f5c] bg-[#fdf1ef] text-gray-700'
                          : 'border-gray-200 text-gray-500 hover:border-[#ed6f5c]'
                      }`}>
                      <span className="w-3.5 h-3.5 rounded-full" style={{ background: t.color }} />
                      {t.label}
                    </button>
                  ))}
                </div>
              </Field>

              {/* Warna custom */}
              <div className="mt-3">
                <Field label="Warna Custom (opsional)" icon={Palette}>
                  <div className="flex items-center gap-2">
                    <input type="color"
                      value={form.support_widget_color || activeThemeColor}
                      onChange={e => setForm(s => ({ ...s, support_widget_color: e.target.value }))}
                      className="w-11 h-10 rounded-lg border border-gray-200 cursor-pointer p-1" />
                    <input
                      value={form.support_widget_color}
                      onChange={e => setForm(s => ({ ...s, support_widget_color: e.target.value }))}
                      placeholder="kosongkan untuk ikut tema"
                      className="flex-1 px-3 py-2 rounded-lg border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#ed6f5c]/30" />
                    {form.support_widget_color && (
                      <button type="button" onClick={() => setForm(s => ({ ...s, support_widget_color: '' }))}
                        className="px-3 py-2 text-xs text-gray-500 hover:text-red-500">Reset</button>
                    )}
                  </div>
                </Field>
              </div>

              {/* Ikon */}
              <div className="mt-3">
                <Field label="Bentuk Ikon" icon={MessageCircle}>
                  <div className="grid grid-cols-4 gap-2">
                    {SUPPORT_ICONS.map(ic => {
                      const Ico = ic.Icon;
                      const aktif = form.support_widget_icon === ic.id;
                      return (
                        <button key={ic.id} type="button"
                          onClick={() => setForm(s => ({ ...s, support_widget_icon: ic.id }))}
                          title={ic.label}
                          className={`py-2.5 rounded-xl border-2 flex items-center justify-center transition-all ${
                            aktif ? 'border-[#ed6f5c] bg-[#fdf1ef]' : 'border-gray-200 hover:border-[#ed6f5c]'
                          }`}>
                          <Ico size={18} className={aktif ? 'text-[#ed6f5c]' : 'text-gray-400'} />
                        </button>
                      );
                    })}
                  </div>
                </Field>
              </div>

              {/* Posisi */}
              <div className="mt-3">
                <Field label="Posisi di Layar" icon={LayoutGrid}>
                  <div className="grid grid-cols-2 gap-2">
                    {[{ id: 'left', label: 'Kiri Bawah' }, { id: 'right', label: 'Kanan Bawah' }].map(p => (
                      <button key={p.id} type="button"
                        onClick={() => setForm(s => ({ ...s, support_widget_position: p.id }))}
                        className={`py-2 rounded-xl border-2 text-xs font-semibold transition-all ${
                          form.support_widget_position === p.id
                            ? 'border-[#ed6f5c] bg-[#ed6f5c] text-white'
                            : 'border-gray-200 text-gray-500 hover:border-[#ed6f5c]'
                        }`}>
                        {p.label}
                      </button>
                    ))}
                  </div>
                  <p className="text-[11px] text-gray-400 mt-1.5">
                    Tombol SOS/panic otomatis ditempatkan tepat di atas tombol support ini.
                  </p>
                </Field>
              </div>

              {/* Pratinjau */}
              <div className="mt-4 rounded-xl border border-gray-200 bg-gray-50 p-4">
                <p className="text-[11px] text-gray-400 mb-2">Pratinjau</p>
                <div className={`flex ${form.support_widget_position === 'right' ? 'justify-end' : 'justify-start'}`}>
                  <span className="relative inline-flex items-center gap-2 h-11 px-4 rounded-full text-white text-sm font-semibold shadow-lg"
                    style={{ background: form.support_widget_color || activeThemeColor }}>
                    {(() => {
                      const Ico = (SUPPORT_ICONS.find(i => i.id === form.support_widget_icon) || SUPPORT_ICONS[0]).Icon;
                      return <Ico size={18} />;
                    })()}
                    Butuh bantuan?
                    <span className="absolute -top-1 -right-1 min-w-[18px] h-[18px] px-1 rounded-full bg-red-500 text-white text-[10px] font-bold flex items-center justify-center">2</span>
                  </span>
                </div>
              </div>
            </div>

            <div className="pt-2">
              <button
                onClick={handleSave}
                disabled={saving}
                className="flex items-center gap-2 px-5 py-2.5 bg-[#ed6f5c] hover:bg-[#e05544] text-white rounded-xl text-sm font-semibold disabled:opacity-50 transition-colors"
              >
                {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
                {saving ? 'Menyimpan...' : 'Simpan Pengaturan'}
              </button>
            </div>
          </div>

          {/* ── Tema Warna ── */}
          <VendorThemeSettings />

          {/* ── Tema Login (tata letak) ── */}
          <VendorLoginLayoutSettings />

          {/* ── Preview Card ── */}
          <div className="lg:col-span-3 bg-gray-50 rounded-xl border border-gray-200 p-5">
            <h2 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-4">Preview — tampilan di aplikasi</h2>
            <div className="flex items-center gap-4 p-4 bg-white rounded-xl border border-gray-200 w-fit shadow-sm">
              <div className="w-14 h-14 rounded-xl bg-gray-100 flex items-center justify-center overflow-hidden flex-shrink-0">
                {logoPreview || logoUrl ? (
                  <img src={logoPreview || logoUrl} alt="logo" className="w-full h-full object-contain p-1" />
                ) : (
                  <Image size={22} className="text-gray-300" />
                )}
              </div>
              <div>
                <p className="text-lg font-bold text-gray-800 leading-tight">{form.app_name || 'Nama Aplikasi'}</p>
                <p className="text-xs text-gray-500">V {form.app_version || '–'} · RT/RW/KEL</p>
                <p className="text-xs text-gray-400 mt-0.5 max-w-xs truncate">{form.app_description || 'Deskripsi aplikasi'}</p>
              </div>
            </div>
          </div>

        </div>
      )}
    </div>
  );
}
