import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { useAuth } from '@/contexts/AuthContext';
import { API_ENDPOINTS } from '@/config/api';
import { toast } from 'sonner';

export default function FundTransactionForm({ open, onClose, onSuccess, funds, initialFundId }) {
    const { token } = useAuth();
    const [loading, setLoading] = useState(false);

    // Form State
    const [financeCategoryId, setFinanceCategoryId] = useState(initialFundId || '');
    const [tipe, setTipe] = useState('pemasukan'); // pemasukan | pengeluaran
    const [jumlah, setJumlah] = useState('');
    const [deskripsi, setDeskripsi] = useState('');
    const [tanggal, setTanggal] = useState(new Date().toISOString().split('T')[0]);

    // Update initialFundId if changed
    React.useEffect(() => {
        if (initialFundId) setFinanceCategoryId(initialFundId);
    }, [initialFundId]);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const payload = {
                finance_category_id: financeCategoryId,
                tipe: tipe,
                jumlah: parseFloat(jumlah),
                deskripsi: deskripsi,
                tanggal: new Date(tanggal).toISOString()
            };

            const res = await fetch(API_ENDPOINTS.BUDGET_FUND_TRANSACTION, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(payload)
            });

            if (!res.ok) throw new Error("Gagal menyimpan transaksi");

            toast.success("Transaksi berhasil disimpan");
            onSuccess();
            onClose();

            // Reset form partly
            setJumlah('');
            setDeskripsi('');
        } catch (error) {
            toast.error(error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle>Input Transaksi Dana</DialogTitle>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-4 py-2">
                    <div className="space-y-2">
                        <Label>Pilih Dana</Label>
                        <Select value={financeCategoryId} onValueChange={setFinanceCategoryId} required>
                            <SelectTrigger>
                                <SelectValue placeholder="Pilih Dana..." />
                            </SelectTrigger>
                            <SelectContent>
                                {funds.map(f => (
                                    <SelectItem key={f.id} value={f.id}>{f.nama}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Jenis Transaksi</Label>
                        <RadioGroup value={tipe} onValueChange={setTipe} className="flex gap-4">
                            <div className="flex items-center space-x-2">
                                <RadioGroupItem value="pemasukan" id="masuk" />
                                <Label htmlFor="masuk" className="text-green-600 font-medium">Masuk (+)</Label>
                            </div>
                            <div className="flex items-center space-x-2">
                                <RadioGroupItem value="pengeluaran" id="keluar" />
                                <Label htmlFor="keluar" className="text-red-600 font-medium">Keluar (-)</Label>
                            </div>
                        </RadioGroup>
                    </div>

                    <div className="space-y-2">
                        <Label>Jumlah (Rp)</Label>
                        <div className="relative">
                            <span className="absolute left-3 top-2.5 text-gray-500 text-sm">Rp</span>
                            <Input
                                type="text"
                                className="pl-9"
                                value={jumlah ? parseFloat(jumlah.toString().replace(/\./g, '')).toLocaleString('id-ID') : ''}
                                onChange={e => {
                                    const value = e.target.value.replace(/\D/g, '');
                                    setJumlah(value);
                                }}
                                placeholder="1.000.000"
                                required
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <Label>Keterangan</Label>
                        <Textarea
                            value={deskripsi}
                            onChange={e => setDeskripsi(e.target.value)}
                            placeholder="Contoh: Topup kas kecil, Biaya konsumsi rapat, dll"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Tanggal</Label>
                            <Input
                                type="date"
                                value={tanggal}
                                onChange={e => setTanggal(e.target.value)}
                                required
                            />
                        </div>
                    </div>

                    <DialogFooter className="mt-4">
                        <Button type="button" variant="outline" onClick={onClose}>Batal</Button>
                        <Button type="submit" disabled={loading}>
                            {loading ? 'Menyimpan...' : 'Simpan Transaksi'}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}
