import { Button } from "@/components/ui/button";

// Pagination generik dipakai di menu Pengguna (RT/RW/Kelurahan) — nomor
// halaman + pilihan jumlah data per halaman (min 25, max 100).
const DEFAULT_PER_PAGE_OPTIONS = [25, 50, 100];

function buildPageNumbers(page, totalPages) {
  const delta = 1;
  const pages = [];
  for (let i = 1; i <= totalPages; i++) {
    if (i === 1 || i === totalPages || (i >= page - delta && i <= page + delta)) {
      pages.push(i);
    } else if (pages[pages.length - 1] !== "...") {
      pages.push("...");
    }
  }
  return pages;
}

export default function TablePagination({
  page,
  perPage,
  totalItems,
  onPageChange,
  onPerPageChange,
  perPageOptions = DEFAULT_PER_PAGE_OPTIONS,
  itemLabel = "data",
}) {
  const totalPages = Math.max(1, Math.ceil(totalItems / perPage));
  const startIndex = totalItems === 0 ? 0 : (page - 1) * perPage + 1;
  const endIndex = Math.min(page * perPage, totalItems);

  return (
    <div className="flex flex-col sm:flex-row items-center justify-between gap-3 px-4 py-3 text-sm text-gray-500 dark:text-gray-400 border-t border-gray-100 dark:border-gray-700">
      <div className="flex items-center gap-3">
        <span>
          {totalItems === 0 ? `0 ${itemLabel}` : `${startIndex}-${endIndex} dari ${totalItems} ${itemLabel}`}
        </span>
        <div className="flex items-center gap-1.5">
          <span className="text-xs">Per halaman:</span>
          <select
            value={perPage}
            onChange={(e) => onPerPageChange(Number(e.target.value))}
            className="text-xs border rounded-md px-2 py-1 bg-white dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100"
          >
            {perPageOptions.map((n) => (
              <option key={n} value={n}>{n}</option>
            ))}
          </select>
        </div>
      </div>

      {totalPages > 1 && (
        <div className="flex items-center gap-1 flex-wrap justify-center">
          <Button
            variant="outline" size="sm"
            disabled={page === 1}
            onClick={() => onPageChange(page - 1)}
          >
            Sebelumnya
          </Button>
          {buildPageNumbers(page, totalPages).map((p, idx) =>
            p === "..." ? (
              <span key={`ellipsis-${idx}`} className="px-1.5 text-gray-400">…</span>
            ) : (
              <Button
                key={p}
                variant={p === page ? undefined : "outline"}
                size="sm"
                className={p === page ? "bg-[var(--rw-primary)] hover:bg-[var(--rw-primary-hover)] text-white min-w-[2.25rem]" : "min-w-[2.25rem]"}
                onClick={() => onPageChange(p)}
              >
                {p}
              </Button>
            )
          )}
          <Button
            variant="outline" size="sm"
            disabled={page === totalPages}
            onClick={() => onPageChange(page + 1)}
          >
            Selanjutnya
          </Button>
        </div>
      )}
    </div>
  );
}
